('mcq', 1, 'ما قيمة البادئة milli (m) بقوى العشرة؟', null, null, '["$10^{-6}$","$10^{-2}$","$10^{3}$","$10^{-3}$"]'::jsonb, 'تذكر', 'تذكر', 'سهل', 'الكتاب ص 17 — البادئات المستخدمة مع وحدات النظام الدولي'),
