('essay', 1, 'أكمل الجدول الآتي بكتابة رمز كل بادئة وقيمتها بقوى العشرة، ثم صنّفها إلى أجزاء أو مضاعفات.', '{"headers":["البادئة","الرمز","القيمة بقوى العشرة","جزء أم مضاعف"],"rows":[["kilo","......","......","......"],["centi","......","......","......"],["micro","......","......","......"],["giga","......","......","......"],["nano","......","......","......"]]}'::jsonb, null, null, 'فهم', 'إكمال جدول', 'سهل', 'الكتاب ص 17 — البادئات المستخدمة مع وحدات النظام الدولي'),
