('mcq', 6, 3, 'البادئة femto ورمزها f تساوي $10^{-15}$، وهي أصغر البادئات في جدول البادئات المستخدمة مع وحدات النظام الدولي.', '["pico تساوي $10^{-12}$.","tera تساوي $10^{12}$ (أس موجب).","nano تساوي $10^{-9}$.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (43%)"}],"at":"2026-11-18T12:34:59.061Z"}'::jsonb),
