('mcq', 1, 'ما المقصود بدقة القياس؟', null, null, '["اتفاق نتائج القياس مع القيمة المقبولة التي قاسها خبراء مؤهلون في القياس","درجة الإتقان في القياس، وتعبّر عن مدى تقارب نتائجه بغض النظر عن صحتها","الفرق بين أكبر قيمة وأصغر قيمة يمكن أن تقيسها أداة القياس المستخدمة","عدد مرات تكرار القياس اللازمة للحصول على نتيجة موثوقة يمكن الاعتماد عليها"]'::jsonb, 'تذكر', 'تذكر تعريف', 'سهل', 'الكتاب ص 19 — الدقة والضبط (دقة القياس)'),
('mcq', 2, 'في تعريف دقة القياس عبارة «بغض النظر عن صحتها». أيّ العبارات الآتية توضح معناها؟', null, null, '["القياسات الدقيقة تكون دائمًا مطابقة للقيمة المقبولة للكمية المقيسة","تُحدَّد دقة القياس بمقارنة النتيجة بالقيمة التي قاسها الخبراء","قد تكون القياسات متقاربة جدًا فيما بينها وبعيدة عن القيمة الصحيحة","لا تعتمد دقة القياس على النتائج وإنما على مهارة القائس فقط"]'::jsonb, 'فهم', 'تفسير عبارة', 'متوسط', 'الكتاب ص 19 — الدقة والضبط (دقة القياس)'),
('mcq', 3, 'سجّل طالب نتيجة قياسه للطول على الصورة $(14.0 \pm 0.1)\ \text{cm}$. ماذا يعني المقدار $\pm 0.1\ \text{cm}$؟', null, null, '["أن القيمة المقبولة للطول تساوي 0.1 cm","أن الطول الحقيقي أكبر من 14.0 cm بمقدار 0.1 cm دائمًا","أن الطالب أخطأ في قراءته بمقدار 0.1 cm تمامًا","هامش الخطأ؛ أي أن النتيجة تقع بين 13.9 cm و14.1 cm"]'::jsonb, 'فهم', 'تفسير', 'سهل', 'الكتاب ص 19 — الدقة والضبط (دقة القياس)'),
('mcq', 4, 'يمثل الرسم البياني الآتي قياسات طالبين لطول الطاولة نفسها، حيث يمثل الشريط الرأسي لكل طالب مدى قياساته. ماذا يمثل طول الشريط الرأسي؟', null, '[{"src":"qimg/phys1/c1l2-o08-errorbars.svg","alt":"رسم بياني لقياسات طالبين لطول الطاولة نفسها. المحور الرأسي «طول الطاولة (cm)» مدرّج من 29.6 إلى 31.0 بخطوات 0.2، والمحور الأفقي «الطالب» عليه الطالب 1 والطالب 2. لكل طالب خط أفقي قصير عند متوسط قياساته وشريط رأسي أحمر بطرفين: الطالب 1 متوسطه 30.4 cm وشريطه من 30.0 إلى 30.8 cm (أي بهامش خطأ 0.4 cm)، والطالب 2 متوسطه 30.2 cm وشريطه من 30.1 إلى 30.3 cm (أي بهامش خطأ 0.1 cm)."}]'::jsonb, '["هامش الخطأ؛ وكلما قصر الشريط كانت القياسات أدق","القيمة المقبولة لطول الطاولة التي قاسها الخبراء","عدد مرات القياس التي أجراها كل طالب","مدى اتفاق القياسات مع القيمة المقبولة للطول"]'::jsonb, 'فهم', 'تفسير رسم بياني', 'متوسط', 'الكتاب ص 19 — الشكل 1-9 (بيانات التجربة)'),
('mcq', 5, 'قيل إن «دقة القياس بهذه المسطرة $\pm 0.05\ \text{cm}$». ماذا تعني هذه العبارة؟', null, null, '["أن القراءة بهذه المسطرة مطابقة للقيمة المقبولة للطول دائمًا","أن القراءة قد تزيد أو تنقص عن القيمة المسجلة بما لا يتجاوز 0.05 cm","أن أطول جسم يمكن قياسه بهذه المسطرة يساوي 0.05 cm فقط","أن أصغر تدريج على هذه المسطرة يساوي 0.05 cm تمامًا"]'::jsonb, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 19 — الدقة والضبط (دقة القياس)'),
('mcq', 6, 'أيّ العبارات الآتية تعبّر عن العلاقة بين دقة القياس وهامش الخطأ تعبيرًا صحيحًا؟', null, null, '["كلما كبر هامش الخطأ زادت دقة القياس","لا علاقة بين هامش الخطأ ودقة القياس","كلما صغر هامش الخطأ زادت دقة القياس","تزداد الدقة كلما كانت القيمة المقيسة أكبر"]'::jsonb, 'فهم', 'استنتاج علاقة', 'صعب', 'الكتاب ص 19 — الدقة والضبط (دقة القياس)'),
('mcq', 7, 'أيّ المواقف الآتية يعبّر عن مفهوم دقة القياس؟', null, null, '["قاس طالب كتلة جسم خمس مرات فحصل على قراءات متقاربة جدًا","تطابقت قراءة الطالب مع القيمة التي قاسها خبراء مؤهلون","عاير فني الميزان بقياس كتلة معلومة القيمة","قرأ الطالب التدريج وهو ينظر إليه بشكل عمودي وبعين واحدة"]'::jsonb, 'تطبيق', 'تطبيق المفهوم', 'صعب', 'الكتاب ص 19، 20 — الدقة والضبط'),
('essay', 1, 'وضّح المقصود بدقة القياس، ثم وضّح معنى عبارة «بغض النظر عن صحتها» الواردة في التعريف بمثال من عندك.', null, null, null, 'فهم', 'توضيح مفهوم', 'سهل', 'الكتاب ص 19 — الدقة والضبط (دقة القياس)'),
('essay', 2, 'أجرى طالب تجربة لقياس طول نابض عدة مرات، فتراوحت قياساته بين 14.4 cm و14.8 cm، وكان متوسطها 14.6 cm، فسجّل النتيجة $(14.6 \pm 0.2)\ \text{cm}$. وضّح ما يعنيه المقدار $\pm 0.2\ \text{cm}$، وكيف يرتبط بدقة قياسات الطالب.', null, null, null, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 19 — الدقة والضبط (دقة القياس)'),
('essay', 3, 'أخبرك صديقك أن طوله 182 cm. وضّح مدى دقة هذا القياس، وما الذي يدل عليه تسجيل الطول دون أرقام عشرية؟ وكيف يمكن التعبير عن الطول بدقة أكبر؟', null, null, null, 'تحليل', 'تحليل قياس', 'صعب', 'الكتاب ص 21 — مراجعة (السؤال 17)')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
