from (values
('mcq', 1, 1, 'دقة القياس هي درجة الإتقان في القياس، وتعبّر عن مدى تقارب نتائج القياس بغض النظر عن صحتها.', '["هذا تعريف الضبط لا الدقة.","","هذا يصف مدى الأداة (أقصى ما تقيسه) لا دقة القياس.","تكرار القياس طريقة للحكم على تقارب النتائج، وليس هو تعريف الدقة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-18T12:34:59.064Z"}'::jsonb),
('mcq', 2, 2, 'الدقة تصف تقارب النتائج بعضها من بعض، ولا تشترط أن تكون صحيحة؛ فقد تكون القراءات متقاربة جدًا (دقيقة) لكنها بعيدة عن القيمة المقبولة.', '["مطابقة القيمة المقبولة تتعلق بالضبط؛ فالقياسات الدقيقة قد لا تكون صحيحة.","المقارنة بالقيمة المقبولة تحدد الضبط لا الدقة.","","الدقة تُحكم من تقارب النتائج، وتعتمد على الأداة والطريقة، لا على مهارة القائس فقط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-18T12:34:59.064Z"}'::jsonb),
('mcq', 3, 3, 'المقدار $\pm 0.1\ \text{cm}$ هامش الخطأ الذي يعبّر عن دقة القياس؛ فالنتيجة تقع بين $14.0 - 0.1 = 13.9\ \text{cm}$ و$14.0 + 0.1 = 14.1\ \text{cm}$، وكلما صغر هذا الهامش كان القياس أدق.', '["المقدار $\\pm 0.1\\ \\text{cm}$ لا يمثل القيمة المقبولة، بل مقدار التفاوت المحتمل حول 14.0 cm.","الإشارة $\\pm$ تعني زيادة أو نقصانًا، لا زيادة فقط.","هامش الخطأ حدّ للتفاوت المحتمل في النتيجة زيادة أو نقصانًا، وليس مقدار خطأ محددًا وقع فيه الطالب.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-18T12:34:59.064Z"}'::jsonb),
('mcq', 4, 0, 'طول الشريط يمثل مدى تفاوت القياسات (هامش الخطأ)؛ فالشريط القصير يعني أن القياسات متقاربة، أي أكثر دقة.', '["","القيمة المقبولة غير ممثلة في الرسم؛ فالشريط يمثل تفاوت قياسات الطالب نفسه.","طول الشريط لا يدل على عدد القياسات بل على مدى تفاوتها.","الاتفاق مع القيمة المقبولة هو الضبط، والرسم لا يتضمن قيمة مقبولة للمقارنة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-18T12:34:59.065Z"}'::jsonb),
('mcq', 5, 1, 'الدقة $\pm 0.05\ \text{cm}$ تعني أن هامش الخطأ في القراءة لا يتجاوز 0.05 cm زيادة أو نقصانًا.', '["المطابقة مع القيمة المقبولة وصف للضبط، ولا يضمنها هامش الخطأ.","","هذا يصف مدى المسطرة لا دقتها.","الدقة تساوي نصف أصغر تدريج؛ فأصغر تدريج هنا 0.1 cm لا 0.05 cm."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-18T12:34:59.065Z"}'::jsonb),
('mcq', 6, 2, 'هامش الخطأ يعبّر عن مقدار تفاوت القياسات؛ فكلما صغر كانت القياسات أكثر تقاربًا، أي أكثر دقة.', '["العكس هو الصحيح؛ فهامش الخطأ الكبير يعني تفاوتًا أكبر ودقة أقل.","هامش الخطأ هو مقياس دقة القياس نفسه.","","الدقة لا تعتمد على كبر القيمة المقيسة، بل على تقارب النتائج."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-18T12:34:59.065Z"}'::jsonb),
('mcq', 7, 0, 'قاس الطالب كتلة الجسم خمس مرات فحصل على قراءات متقاربة جدًا؛ وتقارب نتائج القياسات المتكررة فيما بينها هو ما تعبّر عنه دقة القياس.', '["","التطابق مع القيمة المقبولة يعبّر عن الضبط.","المعايرة طريقة لاختبار الضبط في الجهاز.","النظر العمودي من تقنيات القياس الجيد التي تقلل الخطأ الشخصي وتحسّن الضبط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-18T12:34:59.065Z"}'::jsonb),
('essay', 1, null::int, null, null, 'دقة القياس هي درجة الإتقان في القياس، وتعبّر عن مدى تقارب نتائج القياس بغض النظر عن صحتها. أي أن الدقة تهتم بتقارب القراءات فيما بينها فقط، فقد تكون القراءات دقيقة وهي غير صحيحة. مثال: ميزان غير مصفّر يعطي عند وزن جسم كتلته 50.0 g القراءات 52.1 g و52.1 g و52.2 g؛ فهي متقاربة (دقيقة) لكنها بعيدة عن القيمة الصحيحة.', '["تعريف دقة القياس","الدقة تخص تقارب القراءات لا صحتها","مثال مناسب لقراءات متقاربة غير صحيحة"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف","marks":1},{"element":"توضيح العبارة","marks":1},{"element":"المثال","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"يعرّف ويوضح العبارة ويعطي مثالًا مناسبًا"},{"level":"2 درجتان","description":"يحقق عنصرين"},{"level":"1 درجة","description":"يحقق عنصرًا واحدًا"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تعريف الدقة بأنها اتفاق النتيجة مع القيمة المقبولة","إعطاء مثال لقراءات متباعدة","عدّ القياس الدقيق صحيحًا بالضرورة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-18T12:34:59.065Z"}'::jsonb),
('essay', 2, null::int, null, null, 'المقدار $\pm 0.2\ \text{cm}$ هامش الخطأ، ويعني أن قياسات الطالب تفاوتت حول المتوسط 14.6 cm بما لا يزيد على 0.2 cm زيادة أو نقصانًا، فهي تقع بين 14.4 cm و14.8 cm. ويعبّر هامش الخطأ عن الدقة؛ فكلما صغر كانت القياسات أكثر تقاربًا وأكثر دقة، ولو كان هامش الخطأ $\pm 0.1\ \text{cm}$ مثلًا لكانت القياسات أدق.', '["$\\pm 0.2\\ \\text{cm}$ هامش الخطأ","القياسات بين 14.4 cm و14.8 cm حول المتوسط","صغر الهامش يعني دقة أكبر"]'::jsonb, '[]'::jsonb, '[{"element":"تحديد معنى هامش الخطأ","marks":1},{"element":"ربطه بمدى القياسات","marks":1},{"element":"ربطه بالدقة","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"يوضح المعنى ويربطه بمدى القياسات وبالدقة"},{"level":"2 درجتان","description":"يحقق عنصرين"},{"level":"1 درجة","description":"يحقق عنصرًا واحدًا"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ 0.2 cm هو القيمة المقبولة","القول إن الهامش يعني زيادة فقط","القول إن الهامش الأكبر يعني دقة أكبر"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-18T12:34:59.065Z"}'::jsonb),
('essay', 3, null::int, null, null, 'تسجيل الطول 182 cm دون أرقام عشرية يدل على أنه قيس بأداة أصغر تدريج فيها 1 cm تقريبًا، فتكون دقة القياس نصف أصغر تدريج أي نحو $\pm 0.5\ \text{cm}$؛ فالطول الحقيقي يقع تقريبًا بين 181.5 cm و182.5 cm. ولزيادة الدقة يُقاس الطول بأداة ذات تدريج أصغر (مثل مسطرة مليمترية) فيُسجّل الطول بأرقام عشرية، مثل $(182.3 \pm 0.05)\ \text{cm}$.', '["القياس لأقرب 1 cm","الدقة نحو $\\pm 0.5\\ \\text{cm}$","زيادة الدقة باستخدام أداة ذات تدريج أصغر"]'::jsonb, '[]'::jsonb, '[{"element":"استنتاج أن القياس لأقرب 1 cm","marks":1},{"element":"تقدير الدقة","marks":1},{"element":"اقتراح طريقة لزيادة الدقة","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"يستنتج ويقدّر الدقة ويقترح طريقة صحيحة"},{"level":"2 درجتان","description":"يحقق عنصرين"},{"level":"1 درجة","description":"يحقق عنصرًا واحدًا"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن القياس دقيق تمامًا لأنه عدد صحيح","عدّ الدقة $\\pm 1\\ \\text{cm}$ دون تعليل","اقتراح تكرار القياس بالأداة نفسها فقط"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-18T12:34:59.065Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
