('mcq', 6, 2, 'الساعة التي تقرأ لأقرب 0.01 s أصغر تدريجًا، فدقتها $\pm 0.005\ \text{s}$ مقارنة بـ $\pm 0.5\ \text{s}$ للأخرى.', '["القراءة المائلة خطأ شخصي يقلل ضبط القراءة، ولا يزيد الدقة.","تغيير الوحدة لا يغير مقدار هامش الخطأ.","","المقارنة بالرقم القياسي لا تغير دقة الأداة المستخدمة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-18T12:34:59.067Z"}'::jsonb),
('mcq', 7, 0, 'دقة القياس تعتمد على الأداة؛ فهي تساوي نصف أصغر تدريج فيها. أما زاوية النظر وموضع الصفر والفرق عن القيمة المقبولة فتؤثر في الضبط.', '["","اختلاف زاوية النظر يجعل القراءة غير مضبوطة، فهو يؤثر في الضبط لا في الدقة.","عدم بدء الصفر عند الحافة يُزيح جميع القراءات عن القيمة الصحيحة، فيؤثر في الضبط.","الفرق عن القيمة المقبولة مقياس للضبط لا للدقة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-18T12:34:59.067Z"}'::jsonb),
('essay', 1, null::int, null, null, 'تعتمد دقة القياس على: (1) الأداة المستخدمة في القياس: فكلما كانت الأداة ذات تدريج بقيم أصغر كانت القياسات أكثر دقة؛ مثل المسطرة المقسمة إلى 0.1 cm (دقتها $\pm 0.05\ \text{cm}$) مقارنة بمسطرة مقسمة إلى 0.5 cm (دقتها $\pm 0.25\ \text{cm}$). (2) الطريقة المستخدمة في القياس: مثل قياس سمك 100 ورقة معًا ثم القسمة على 100 بدل قياس ورقة واحدة، فيصغر هامش الخطأ لسمك الورقة الواحدة.', '["العامل الأول: الأداة (أصغر تدريج)","العامل الثاني: طريقة القياس","مثال صحيح لكل عامل"]'::jsonb, '[]'::jsonb, '[{"element":"ذكر الأداة وأثرها","marks":1},{"element":"ذكر الطريقة وأثرها","marks":1},{"element":"الأمثلة","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"يحدد العاملين ويوضح أثرهما بمثالين صحيحين"},{"level":"2 درجتان","description":"يحدد العاملين دون أمثلة مناسبة، أو عاملًا واحدًا بمثال"},{"level":"1 درجة","description":"يذكر عاملًا واحدًا فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ذكر القيمة المقبولة عاملًا في الدقة","ذكر زاوية النظر عاملًا في الدقة بدل الضبط","الاكتفاء بالأداة دون الطريقة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-18T12:34:59.067Z"}'::jsonb),
('essay', 2, null::int, null, null, 'أصغر تدريج في المقياس A يساوي $1\ ^\circ\text{C}$، وفي المقياس B يساوي $5\ ^\circ\text{C}$. لذلك يعطي المقياس A قياسًا أكثر دقة؛ لأن الأداة ذات التدريج الأصغر تعطي قياسات أكثر دقة (هامش خطأ $\pm 0.5\ ^\circ\text{C}$ مقابل $\pm 2.5\ ^\circ\text{C}$ للمقياس B)، رغم أن المقياسين يقيسان درجة الحرارة نفسها.', '["أصغر تدريج: A = $1\\ ^\\circ\\text{C}$ وB = $5\\ ^\\circ\\text{C}$","A أكثر دقة","التعليل: التدريج الأصغر يعطي دقة أكبر"]'::jsonb, '[]'::jsonb, '[{"element":"تحديد أصغر تدريج في المقياسين","marks":1},{"element":"الحكم الصحيح","marks":1},{"element":"التعليل","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"يحدد أصغر تدريج ويحكم ويعلل صحيحًا"},{"level":"2 درجتان","description":"يحكم ويعلل دون تحديد التدريجين، أو العكس"},{"level":"1 درجة","description":"يحكم صحيحًا دون تعليل"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ أصغر تدريج $10\\ ^\\circ\\text{C}$ لأنه الفرق بين الأرقام المكتوبة","القول إن المقياسين متساويان لأنهما يقرآن الدرجة نفسها","الحكم على الدقة من طول المقياس"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-18T12:34:59.067Z"}'::jsonb),
('essay', 3, null::int, null, null, 'بدل قياس زمن دورة واحدة، يقيس الطالب زمن عدد كبير من الدورات (مثل 10 دورات) ثم يقسم الزمن الكلي على عدد الدورات. هامش الخطأ في قراءة الساعة $\pm 0.05\ \text{s}$ (نصف أصغر تدريج) سواء قاس دورة واحدة أو عشر دورات، لكن عند القسمة على 10 يصبح هامش الخطأ في زمن الدورة الواحدة نحو $\pm 0.005\ \text{s}$، فتزداد الدقة. وهذا يبين أن الدقة تعتمد على طريقة القياس إضافة إلى الأداة.', '["قياس زمن عدد من الدورات ثم القسمة","هامش خطأ الساعة $\\pm 0.05\\ \\text{s}$ ثابت للقراءة","القسمة على عدد الدورات تصغّر هامش الخطأ ($\\pm 0.005\\ \\text{s}$ لعشر دورات)"]'::jsonb, '["هامش الخطأ للقراءة $= \\frac{0.1}{2} = 0.05\\ \\text{s}$","لعشر دورات: هامش الخطأ لكل دورة $= \\frac{0.05}{10} = 0.005\\ \\text{s}$"]'::jsonb, '[{"element":"اقتراح الطريقة","marks":1},{"element":"تحديد هامش خطأ الساعة","marks":1},{"element":"تفسير زيادة الدقة","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"يقترح الطريقة ويفسر زيادة الدقة حسابيًا"},{"level":"2 درجتان","description":"يقترح الطريقة ويفسر دون حساب، أو يحسب دون تفسير"},{"level":"1 درجة","description":"يقترح الطريقة دون تفسير"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["اقتراح تكرار قياس دورة واحدة بالساعة نفسها فقط","اقتراح القراءة بسرعة أكبر","عدّ هامش خطأ الساعة 0.1 s بدل 0.05 s"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-18T12:34:59.067Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
