('mcq', 3, 'استخدم عالمان تقنية التأريخ بالكربون المشع لتحديد عمر عينتين خشبيتين متشابهتين. فوجد العالم A أن العمر $(3120 \pm 60)$ سنة، ووجد العالم B أن العمر $(3080 \pm 35)$ سنة. أيّ العبارات الآتية صحيح؟', null, null, '["قياس العالم A أكثر دقة من قياس العالم B","قياس العالم B أكثر دقة من قياس العالم A","قياس العالم A أكثر ضبطًا من قياس العالم B","قياس العالم B أكثر ضبطًا من قياس العالم A"]'::jsonb, 'تحليل', 'مقارنة قياسات', 'متوسط', 'الكتاب ص 29 — اختبار مقنن (السؤال 1)'),
('mcq', 4, 'قاس أربعة طلاب كتلة الجسم نفسه ثلاث مرات، وسجلوا النتائج في الجدول الآتي. أيّ الطلاب قياساته الأكثر دقة؟', '{"headers":["الطالب","القراءة 1 (g)","القراءة 2 (g)","القراءة 3 (g)"],"rows":[["أحمد","52.3","52.9","52.6"],["خالد","51.8","51.9","51.8"],["سعد","52.5","52.0","52.4"],["فهد","53.1","52.2","52.7"]]}'::jsonb, null, '["أحمد","فهد","سعد","خالد"]'::jsonb, 'تحليل', 'تحليل بيانات جدول', 'متوسط', 'الكتاب ص 19 — الشكل 1-9: القياسات الأكثر دقة'),
