from (values
('mcq', 1, 1, 'قياسات الطالب 2 تتراوح بين 25.0 cm و25.2 cm، أي $(25.1 \pm 0.1)\ \text{cm}$، وهو أصغر هامش خطأ بين الطلاب، فقياساته الأكثر تقاربًا والأكثر دقة.', '["هامش خطأ الطالب 1 يساوي $\\pm 0.3\\ \\text{cm}$، وهو أكبر من هامش الطالب 2.","","الطالب 3 أكبر متوسطًا لكن هامش خطئه $\\pm 0.5\\ \\text{cm}$ هو الأكبر، فقياساته الأقل دقة.","الطالب 4 هامش خطئه $\\pm 0.2\\ \\text{cm}$، وهو أكبر من هامش الطالب 2؛ وكونه أصغر متوسطًا لا علاقة له بالدقة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (42%)"}],"at":"2026-11-18T12:34:59.070Z"}'::jsonb),
('mcq', 2, 2, 'الدقة تُحكم من هامش الخطأ؛ وهامش خطأ الأول $0.002 \times 10^{8}\ \text{m/s}$ أصغر من هامش خطأ الثاني $0.005 \times 10^{8}\ \text{m/s}$، فالقياس الأول أكثر دقة.', '["القرب من القيمة المعروفة يتعلق بالضبط لا بالدقة.","تساوي رتبة القيمة ($10^{8}$) لا يعني تساوي الدقة؛ فهامشا الخطأ مختلفان.","","الحكم على الدقة لا يحتاج إلى القيمة المقبولة؛ فهي تعتمد على تقارب القياسات (هامش الخطأ)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-18T12:34:59.070Z"}'::jsonb),
('mcq', 3, 1, 'هامش خطأ العالم B ($\pm 35$ سنة) أصغر من هامش خطأ العالم A ($\pm 60$ سنة)، فقياس B أكثر دقة. أما الضبط فلا يمكن الحكم عليه لعدم معرفة القيمة المقبولة لعمر العينة.', '["هامش خطأ A أكبر، فقياسه أقل دقة لا أكثر.","","الضبط يتطلب المقارنة بقيمة مقبولة غير معطاة، فلا يمكن الحكم به.","لا يمكن الحكم على الضبط دون قيمة مقبولة، والمعطيات تسمح بالحكم على الدقة فقط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (3%)"}],"at":"2026-11-18T12:34:59.071Z"}'::jsonb),
('mcq', 4, 3, 'قراءات خالد (51.8 g و51.9 g و51.8 g) تتفاوت بمقدار 0.1 g فقط، وهو أصغر تفاوت بين الطلاب، فقياساته الأكثر تقاربًا والأكثر دقة.', '["قراءات أحمد تتفاوت بين 52.3 g و52.9 g (0.6 g)، فهي أقل تقاربًا من قراءات خالد.","قراءات فهد تتفاوت بين 52.2 g و53.1 g (0.9 g)، وهي الأقل دقة؛ وكبر قيمها لا يجعلها أدق.","قراءات سعد تتفاوت بين 52.0 g و52.5 g (0.5 g)، فهي أقل تقاربًا من قراءات خالد.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-11-18T12:34:59.071Z"}'::jsonb),
('mcq', 5, 0, 'القياس $(12.350 \pm 0.005)\ \text{cm}$ له أصغر هامش خطأ (0.005 cm)، فهو الأكثر دقة.', '["","هامش الخطأ 0.05 cm أكبر بعشر مرات من 0.005 cm.","هامش الخطأ 0.25 cm كبير نسبيًا، فالقياس أقل دقة.","هامش الخطأ 0.5 cm هو الأكبر، فالقياس الأقل دقة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-18T12:34:59.071Z"}'::jsonb),
('mcq', 6, 3, 'الدقة تُحكم من تقارب القياسات (طول شريط هامش الخطأ) بغض النظر عن صحتها؛ وشريط الطالب 1 ($\pm 0.06\ \text{m/s}^2$) هو الأقصر، فقياساته الأكثر دقة رغم بعدها عن القيمة المقبولة.', '["مساواة المتوسط للقيمة المقبولة تتعلق بالضبط، وشريط الطالب 2 ($\\pm 0.30\\ \\text{m/s}^2$) هو الأطول، فقياساته الأقل دقة.","اقتراب المتوسط من القيمة المقبولة يتعلق بالضبط، وشريط الطالب 3 ($\\pm 0.18\\ \\text{m/s}^2$) أطول من شريط الطالب 1.","أطوال الأشرطة مختلفة، فدقة الطلاب مختلفة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (35%)"}],"at":"2026-11-18T12:34:59.071Z"}'::jsonb),
('mcq', 7, 1, 'الدقة تعتمد على هامش الخطأ (تقارب القياسات)؛ وهامش خطأ الزميل ($\pm 0.08\ \text{m/s}^2$) أصغر من هامش الطالب ($\pm 0.40\ \text{m/s}^2$)، فقياس الزميل أدق. أما مساواة القيمة المقبولة فتجعل قياس الطالب أكثر ضبطًا لا أكثر دقة.', '["هذا يخلط بين الدقة والضبط؛ فالقرب من القيمة المقبولة هو الضبط.","","هامش الخطأ الكبير يدل على تفاوت أكبر، أي دقة أقل، لا على عدد أكبر من القياسات.","هامشا الخطأ مختلفان، والقيمتان مختلفتان، فلا يتساوى القياسان في الدقة ولا في الضبط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-18T12:34:59.071Z"}'::jsonb),
('essay', 1, null::int, null, null, '(a) الطالب 1: $(20.4 \pm 0.3)\ \text{cm}$، الطالب 2: $(20.7 \pm 0.2)\ \text{cm}$، الطالب 3: $(20.1 \pm 0.4)\ \text{cm}$. (b) الترتيب من الأكثر دقة: الطالب 2 ثم الطالب 1 ثم الطالب 3؛ لأن الدقة تزداد كلما صغر هامش الخطأ (0.2 < 0.3 < 0.4)، أي كلما كانت القياسات أكثر تقاربًا.', '["قراءة النتائج الثلاث من الرسم","الترتيب: 2 ثم 1 ثم 3","التعليل بصغر هامش الخطأ"]'::jsonb, '["هامش الخطأ = نصف طول الشريط","الطالب 1: $\\frac{20.7 - 20.1}{2} = 0.3$","الطالب 2: $\\frac{20.9 - 20.5}{2} = 0.2$، الطالب 3: $\\frac{20.5 - 19.7}{2} = 0.4$"]'::jsonb, '[{"element":"(a) كتابة النتائج","marks":1},{"element":"(b) الترتيب","marks":1},{"element":"التعليل","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"يكتب النتائج ويرتب ويعلل صحيحًا"},{"level":"2 درجتان","description":"يرتب ويعلل مع خطأ في كتابة النتائج، أو العكس"},{"level":"1 درجة","description":"يحدد الطالب الأكثر دقة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الترتيب حسب قيمة المتوسط بدل هامش الخطأ","عدّ هامش الخطأ طول الشريط كاملًا","الحكم بأن الطالب 2 أدق لأن متوسطه الأكبر"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (42%)"}],"at":"2026-11-18T12:34:59.072Z"}'::jsonb),
('essay', 2, null::int, null, null, 'مدى تفاوت قراءات المجموعة الأولى: $14.5 - 14.1 = 0.4\ \text{s}$، ومدى تفاوت قراءات المجموعة الثانية: $14.7 - 13.8 = 0.9\ \text{s}$. متوسط كل مجموعة 14.3 s، لكن قراءات المجموعة الأولى أكثر تقاربًا، فقياساتها أكثر دقة (نحو $(14.3 \pm 0.2)\ \text{s}$ مقابل نحو $(14.3 \pm 0.45)\ \text{s}$ للثانية).', '["حساب تفاوت المجموعة الأولى 0.4 s","حساب تفاوت المجموعة الثانية 0.9 s","الحكم: المجموعة الأولى أدق رغم تساوي المتوسطين"]'::jsonb, '["المجموعة الأولى: أكبر قراءة 14.5 s وأصغرها 14.1 s، التفاوت 0.4 s","المجموعة الثانية: أكبر قراءة 14.7 s وأصغرها 13.8 s، التفاوت 0.9 s","المتوسطان: $\\frac{71.5}{5} = 14.3\\ \\text{s}$ لكل منهما"]'::jsonb, '[{"element":"تفاوت المجموعة الأولى","marks":1},{"element":"تفاوت المجموعة الثانية","marks":1},{"element":"الحكم الصحيح مع التعليل","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"يحسب التفاوتين ويحكم معللًا"},{"level":"2 درجتان","description":"يحكم صحيحًا مع حساب تفاوت واحد"},{"level":"1 درجة","description":"يحكم صحيحًا دون حساب أو تعليل"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الحكم بتساوي الدقة لتساوي المتوسطين","المقارنة بين أكبر القراءات فقط","الخلط بين الدقة والضبط"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-18T12:34:59.072Z"}'::jsonb),
('essay', 3, null::int, null, null, '(a) النتيجة الأولى: بين 44.7 cm و45.7 cm. النتيجة الثانية: بين 45.21 cm و45.31 cm. (b) الدقة نصف أصغر تدريج، فأصغر تدريج في الأداة الأولى $2 \times 0.5 = 1\ \text{cm}$، وفي الثانية $2 \times 0.05 = 0.1\ \text{cm}$. (c) القياس الثاني أكثر دقة؛ لأن هامش خطئه أصغر بعشر مرات، فمدى القيم الممكنة أضيق.', '["(a) 44.7–45.7 cm و45.21–45.31 cm","(b) 1 cm و0.1 cm","(c) الثاني أدق لصغر هامش الخطأ"]'::jsonb, '["$45.2 - 0.5 = 44.7$، $45.2 + 0.5 = 45.7$","$45.26 - 0.05 = 45.21$، $45.26 + 0.05 = 45.31$","أصغر تدريج = 2 × الدقة"]'::jsonb, '[{"element":"(a) المديان","marks":1},{"element":"(b) أصغر تدريج لكل أداة","marks":1},{"element":"(c) الحكم مع التعليل","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"يجيب عن الفروع الثلاثة صحيحة"},{"level":"2 درجتان","description":"يجيب عن فرعين"},{"level":"1 درجة","description":"يجيب عن فرع واحد"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ أصغر تدريج مساويًا لهامش الخطأ","الحكم بأن الأول أدق لأن رقمه أبسط","خطأ في جمع هامش الخطأ وطرحه"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-18T12:34:59.072Z"}'::jsonb)
