('mcq', 3, 'قاس أربعة طلاب كتلة جسم قيمتها المقبولة 50.0 g، ومُثّلت نتائجهم في الرسم الآتي. ما الذي يجعل نتيجة الطالب B أكثر ضبطًا من نتيجة الطالب C؟', null, '[{"src":"qimg/phys1/c1l2-eb-mass.svg","alt":"رسم بياني بأعمدة خطأ: المحور الأفقي «الطالب» وعليه أربعة طلاب A وB وC وD، والمحور الرأسي «الكتلة (g)» من 47.5 إلى 52 بتدريج 0.5. خط أخضر أفقي متقطع عند 50.0 g مكتوب عليه «القيمة المقبولة». نتيجة الطالب A تساوي 48.6 g بعمود خطأ مقداره 0.2 g في كل اتجاه، ونتيجة B تساوي 50.1 g بعمود خطأ مقداره 0.2 g في كل اتجاه، ونتيجة C تساوي 51.2 g بعمود خطأ مقداره 0.2 g في كل اتجاه، ونتيجة D تساوي 49.0 g بعمود خطأ مقداره 0.2 g في كل اتجاه."}]'::jsonb, '["أن نتيجة B أقرب إلى القيمة المقبولة","صغر هامش الخطأ في نتيجة B مقارنة بنتيجة C","أن نتيجة B أكبر من القيمة المقبولة","أن نتيجة B مكتوبة بأرقام معنوية أكثر"]'::jsonb, 'فهم', 'تفسير مفهوم من رسم', 'متوسط', 'الكتاب ص 19–20 — الضبط والقيمة المقبولة'),
('mcq', 4, 'وُضعت الكتلة المعيارية نفسها (100.0 g) على ميزانين، فكانت القراءتان كما في الشكل الآتي. أيّ العبارات الآتية صحيحة؟', null, '[{"src":"qimg/phys1/c1l2-cal-o12.svg","alt":"ميزانان رقميان متماثلان، على كفة كل منهما كتلة معيارية مكتوب عليها 100.0 g. شاشة الميزان 1 تعرض 100.0 g، وشاشة الميزان 2 تعرض 103.4 g."}]'::jsonb, '["الميزان 2 أكثر ضبطًا لأن قراءته أكبر من قراءة الميزان 1","الميزان 1 مضبوط، أما الميزان 2 فغير مضبوط لأن قراءته تبتعد عن القيمة المعتمدة","الميزانان مضبوطان لأن كلًّا منهما يعرض القراءة إلى أقرب 0.1 g","لا يمكن الحكم على ضبط الميزانين قبل تكرار القياس عدة مرات"]'::jsonb, 'فهم', 'تفسير مفهوم من شكل', 'متوسط', 'الكتاب ص 20 — الضبط (الشكل 1-11)'),
('mcq', 5, 'ما الذي يلزم معرفته للحكم على مدى ضبط نتيجة قياس؟', null, null, '["قيمة أصغر تدريج في أداة القياس","عدد مرات تكرار القياس نفسه","متوسط قياسات الطالب نفسه للكمية المقيسة","القيمة المقبولة للكمية المقيسة"]'::jsonb, 'فهم', 'تفسير مفهوم', 'متوسط', 'الكتاب ص 20 — الضبط والقيمة المقبولة'),
('mcq', 6, 'إذا مثّل مركز كل هدف في الشكل الآتي القيمة المقبولة، ومثّلت كل إصابة نتيجة قياس، ففي أيّ الأهداف تتفق جميع النتائج مع القيمة المقبولة اتفاقًا أكبر؟', null, '[{"src":"qimg/phys1/c1l2-tgt-order.svg","alt":"أربعة أهداف رماية، مركز كل منها نقطة حمراء. الهدف 1: خمس إصابات متقاربة جدًّا بعضها من بعض لكنها متجمعة في أعلى يمين الهدف بعيدًا عن المركز. الهدف 2: خمس إصابات متقاربة جدًّا ومتجمعة على المركز نفسه. الهدف 3: خمس إصابات متفرقة ومتباعدة بعضها عن بعض وتقع كلها في أعلى يمين الهدف بعيدًا عن المركز. الهدف 4: خمس إصابات متفرقة موزعة حول المركز من جهاته المختلفة على بعد متوسط منه."}]'::jsonb, '["الهدف 1","الهدف 2","الهدف 3","الهدف 4"]'::jsonb, 'تحليل', 'تفسير مفهوم من شكل', 'صعب', 'الكتاب ص 20 — الضبط والقيمة المقبولة'),
('mcq', 7, 'كان صفر ميزان غير معاير، فأعطى قراءات متقاربة جدًّا بعضها من بعض عند تكرار قياس كتلة جسم. كيف توصف هذه القراءات؟', null, null, '["مضبوطة لأنها تتكرر بالقيمة نفسها تقريبًا","مضبوطة ما دام الميزان رقميًّا ويعرض قراءة ثابتة","متقاربة لكنها غير مضبوطة","غير متقاربة وغير مضبوطة بسبب خطأ الصفر"]'::jsonb, 'فهم', 'تفسير موقف', 'صعب', 'الكتاب ص 19–20 — الدقة والضبط ومعايرة النقطتين'),
('essay', 1, 'وضّح المقصود بالضبط في القياس، ثم بيّن: (أ) القيمة التي تُقارَن بها نتيجة القياس للحكم على ضبطها. (ب) من الذي يحدد هذه القيمة.', null, null, null, 'فهم', 'توضيح مفهوم', 'سهل', 'الكتاب ص 20، 25 — الضبط والقيمة المقبولة'),
('essay', 2, 'يمثل مركز الهدف في الشكل الآتي القيمة المقبولة، وتمثل كل إصابة نتيجة قياس. (أ) هل النتائج مضبوطة؟ علّل. (ب) ماذا تستنتج عن العلاقة بين تقارب النتائج بعضها من بعض وضبطها؟', null, '[{"src":"qimg/phys1/c1l2-tgt-single.svg","alt":"هدف رماية من أربع حلقات متحدة المركز ومركزه نقطة حمراء. توجد خمس إصابات (علامات ×) متقاربة جدًّا بعضها من بعض، متجمعة في الجزء العلوي الأيمن من الهدف قرب الحلقة الخارجية الثانية، بعيدة عن المركز."}]'::jsonb, null, 'فهم', 'تفسير من شكل', 'متوسط', 'الكتاب ص 19–20 — الدقة والضبط'),
('essay', 3, 'قاس طالب طول طاولة ثلاث مرات بمسطرة مترية فحصل على 120.4 cm و120.5 cm و120.4 cm، في حين أن طولها المقبول الذي قاسه خبراء مؤهلون 122.0 cm. (أ) هل قياسات الطالب مضبوطة؟ وضّح إجابتك بحساب الفرق بين متوسط قياساته والقيمة المقبولة. (ب) اقترح سببًا محتملًا لذلك وطريقة لتحسين ضبط قياسه.', null, null, null, 'تحليل', 'تفسير موقف تجريبي', 'صعب', 'الكتاب ص 19–21 — الضبط (سؤال المراجعة 14)')
