('mcq', 1, 2, 'يصف الضبط اتفاق نتائج القياس مع القيمة المقبولة في القياس، أي مدى صحة النتيجة.', '["هذا وصف دقة القياس، وهي تقارب النتائج بعضها من بعض، لا اتفاقها مع القيمة المقبولة.","هذا يحدد دقة الأداة، ولا علاقة له بمقارنة النتيجة بالقيمة المقبولة.","","هذا تعريف القياس نفسه، لا تعريف الضبط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-18T12:34:59.073Z"}'::jsonb),
('mcq', 2, 0, 'القياس المضبوط هو الذي تتفق نتيجته مع القيمة المقبولة، أي تكون قريبة منها.', '["","تكرار النتيجة نفسها يدل على الدقة؛ فقد تتكرر نتيجة بعيدة عن القيمة المقبولة.","صغر التدريج يزيد دقة القياس، ولا يضمن اتفاق النتيجة مع القيمة المقبولة.","كثرة الأرقام المعنوية لا تجعل النتيجة قريبة من القيمة المقبولة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-18T12:34:59.073Z"}'::jsonb),
('mcq', 3, 0, 'الضبط اتفاق النتيجة مع القيمة المقبولة: نتيجة B (50.1 g) تبعد 0.1 g عن 50.0 g، بينما تبعد نتيجة C (51.2 g) بمقدار 1.2 g؛ لذا B أكثر ضبطًا.', '["","هامش الخطأ في النتيجتين متساوٍ ($\\pm 0.2\\ \\text{g}$)، كما أن هامش الخطأ يتعلق بالدقة لا بالضبط.","نتيجة C أيضًا أكبر من القيمة المقبولة؛ فالضبط يحدده مقدار البعد عن القيمة المقبولة لا جهته.","النتيجتان مكتوبتان بعدد الأرقام المعنوية نفسه (ثلاثة أرقام)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-18T12:34:59.073Z"}'::jsonb),
('mcq', 4, 1, 'الضبط يُختبر بقياس كمية معلومة القيمة: قراءة الميزان 1 تساوي القيمة المعتمدة 100.0 g، وقراءة الميزان 2 (103.4 g) تختلف عنها؛ فالميزان 2 غير مضبوط.', '["كبر القراءة لا يعني ضبطًا؛ فالمعيار هو اتفاق القراءة مع القيمة المعتمدة 100.0 g.","","عرض القراءة إلى أقرب 0.1 g يتعلق بالدقة؛ والميزان 2 يبتعد 3.4 g عن القيمة المعتمدة.","الحكم على الضبط يكون بمقارنة القراءة بقيمة معتمدة، وهي معلومة هنا (100.0 g)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-11-18T12:34:59.073Z"}'::jsonb),
('mcq', 5, 3, 'يصف الضبط اتفاق نتائج القياس مع القيمة المقبولة؛ فلا يمكن الحكم عليه دون معرفة هذه القيمة.', '["أصغر تدريج يحدد دقة الأداة، ولا يكشف بُعد النتيجة عن القيمة الصحيحة.","التكرار يبين تقارب القراءات (الدقة)، ولا يكفي للحكم على صحتها.","متوسط قياسات الطالب نتيجة تجريبية يُحكم على ضبطها، وليس مرجعًا للحكم.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-18T12:34:59.073Z"}'::jsonb),
('mcq', 6, 1, 'الضبط اتفاق النتائج مع القيمة المقبولة (المركز). في الهدف 2 تقع جميع الإصابات على المركز تقريبًا، فهي الأكثر ضبطًا.', '["إصابات الهدف 1 متقاربة بعضها من بعض (دقيقة)، لكنها بعيدة عن المركز؛ فهي غير مضبوطة.","","إصابات الهدف 3 متفرقة وبعيدة عن المركز؛ فهي غير مضبوطة وغير دقيقة.","إصابات الهدف 4 موزعة حول المركز لكن كل منها يبعد عنه مسافة واضحة؛ فاتفاق كل نتيجة مع القيمة المقبولة أقل من الهدف 2."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-11-18T12:34:59.074Z"}'::jsonb),
('mcq', 7, 2, 'خطأ معايرة الصفر يُبعد جميع القراءات عن القيمة المقبولة بالمقدار نفسه؛ فتبقى متقاربة (دقيقة) لكنها غير مضبوطة.', '["تكرار القراءة يدل على الدقة، ولا يجعلها متفقة مع القيمة المقبولة.","كون الميزان رقميًّا لا يمنع خطأ معايرة الصفر الذي يُبعد جميع القراءات عن القيمة المقبولة.","","القراءات متقاربة كما في نص السؤال؛ فخطأ الصفر يزيح القراءات كلها بالمقدار نفسه ولا يفرّقها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-11-18T12:34:59.074Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الضبط هو اتفاق نتائج القياس مع القيمة المقبولة في القياس. (أ) تُقارن النتيجة بالقيمة المقبولة. (ب) القيمة المقبولة هي القيمة المعتمدة التي قاسها خبراء مؤهلون.', '["الضبط: اتفاق نتائج القياس مع القيمة المقبولة","المقارنة تكون بالقيمة المقبولة","القيمة المقبولة يحددها خبراء مؤهلون (قيمة معتمدة)"]'::jsonb, '[]'::jsonb, '[{"element":"تعريف الضبط","marks":2},{"element":"القيمة المرجعية","marks":1},{"element":"مصدر القيمة المقبولة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تعريف صحيح للضبط مع تحديد القيمة المقبولة ومصدرها"},{"level":"2–3 درجات","description":"تعريف صحيح مع نقص في (أ) أو (ب)"},{"level":"1 درجة","description":"يذكر أن الضبط يتعلق بصحة النتيجة دون ربطه بالقيمة المقبولة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تعريف الضبط بأنه تقارب النتائج بعضها من بعض (وهذا تعريف الدقة)","عدّ متوسط قياسات الطالب نفسه قيمة مقبولة","إغفال أن القيمة المقبولة يحددها خبراء مؤهلون"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-18T12:34:59.074Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) النتائج غير مضبوطة؛ لأنها جميعًا بعيدة عن مركز الهدف الذي يمثل القيمة المقبولة. (ب) النتائج متقاربة جدًّا بعضها من بعض (دقيقة)، ومع ذلك فهي غير مضبوطة؛ فتقارب النتائج لا يضمن اتفاقها مع القيمة المقبولة، والضبط يُحكم عليه بالمقارنة بالقيمة المقبولة.', '["النتائج غير مضبوطة","التعليل: بعدها عن المركز (القيمة المقبولة)","النتائج متقاربة (دقيقة)","التقارب لا يضمن الضبط"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم على الضبط","marks":1},{"element":"التعليل","marks":1},{"element":"وصف تقارب النتائج","marks":1},{"element":"الاستنتاج","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حكم صحيح مع تعليل واستنتاج سليم للعلاقة"},{"level":"2–3 درجات","description":"حكم صحيح مع تعليل ناقص أو استنتاج ناقص"},{"level":"1 درجة","description":"حكم صحيح دون تعليل"},{"level":"صفر","description":"الحكم بأن النتائج مضبوطة لأنها متقاربة، أو لا إجابة"}]'::jsonb, '["الحكم بأن النتائج مضبوطة لأنها متقاربة","الخلط بين الدقة والضبط","عدم ربط الضبط بمركز الهدف"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-11-18T12:34:59.074Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) متوسط القياسات = $\frac{120.4 + 120.5 + 120.4}{3} \approx 120.4\ \text{cm}$، والفرق عن القيمة المقبولة = $122.0 - 120.4 = 1.6\ \text{cm}$؛ فالقياسات غير مضبوطة لأنها لا تتفق مع القيمة المقبولة، مع أنها متقاربة بعضها من بعض. (ب) من الأسباب المحتملة أن صفر المسطرة لا يبدأ عند حافتها أو أن المسطرة غير معايرة أو أن القراءة أُخذت بشكل مائل؛ ولتحسين الضبط تُستخدم مسطرة معايرة، ويوضع طرف الطاولة عند صفر التدريج تمامًا، ويُقرأ التدريج بالنظر عموديًّا وبعين واحدة.', '["حساب المتوسط ≈ 120.4 cm","حساب الفرق 1.6 cm","الحكم: القياسات غير مضبوطة مع أنها متقاربة","سبب محتمل مقبول","طريقة تحسين مناسبة"]'::jsonb, '["المتوسط = $\\frac{120.4 + 120.5 + 120.4}{3} = 120.43 \\approx 120.4\\ \\text{cm}$","الفرق = $122.0 - 120.4 = 1.6\\ \\text{cm}$","الفرق كبير مقارنة بتقارب القراءات (0.1 cm)؛ إذن غير مضبوطة"]'::jsonb, '[{"element":"المتوسط","marks":1},{"element":"الفرق","marks":1},{"element":"الحكم على الضبط","marks":1},{"element":"السبب المحتمل","marks":1},{"element":"طريقة التحسين","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"حسابات صحيحة مع حكم وسبب وتحسين مناسبين"},{"level":"3–4 درجات","description":"حكم صحيح مع خطأ في الحساب أو نقص في السبب أو التحسين"},{"level":"1–2 درجة","description":"حكم صحيح دون حساب أو تعليل"},{"level":"صفر","description":"الحكم بأن القياسات مضبوطة لتقاربها، أو لا إجابة"}]'::jsonb, '["الحكم بأن القياسات مضبوطة لأنها متقاربة","اقتراح تكرار القياس بالطريقة نفسها لتحسين الضبط","الخطأ في حساب المتوسط أو الفرق"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-11-18T12:34:59.074Z"}'::jsonb)
