('mcq', 1, 0, 'الطريقة الشائعة لاختبار الضبط في الجهاز تسمى معايرة النقطتين.', '["","اختلاف زاوية النظر خطأ شخصي في القراءة، وليس طريقة لاختبار ضبط الجهاز.","تحليل الوحدات طريقة للتحقق من صحة الوحدات في الحل، لا لاختبار الجهاز.","حساب المتوسط لا يكشف ابتعاد الجهاز عن القيم المعتمدة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-11-18T12:34:59.077Z"}'::jsonb),
('mcq', 2, 3, 'معايرة النقطتين تتم أولًا بمعايرة صفر الجهاز (الكفة فارغة والقراءة 0.0 g)، ثم بمعايرته على كمية ذات قيمة معتمدة.', '["الخطوة الأولى تتم والكفة فارغة؛ فهي لمعايرة الصفر لا أكبر قراءة.","أصغر تدريج يحدد دقة الميزان، ولا يتغير بالمعايرة.","الكتلة المعيارية قيمتها معتمدة، وتُستخدم في الخطوة الثانية.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (39%)"}],"at":"2026-11-18T12:34:59.077Z"}'::jsonb),
('mcq', 3, 2, 'الميزان يعرض 2.5 g والكفة فارغة؛ أي إن صفره غير مضبوط. والخطوة الأولى في معايرة النقطتين هي معايرة صفر الجهاز.', '["معايرة النقطتين تبدأ بمعايرة الصفر أولًا، ثم المعايرة بالقيمة المعتمدة.","المشكلة في الجهاز نفسه لا في زاوية القراءة؛ فالشاشة تعرض 2.5 g والكفة فارغة.","","خطأ الصفر يتكرر في كل قراءة، فلا يزيله التكرار."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-18T12:34:59.077Z"}'::jsonb),
('mcq', 4, 1, 'الخطوة الثانية في معايرة النقطتين هي معايرة الجهاز بحيث يعطي قيمة مضبوطة عندما يقيس كمية ذات قيمة معتمدة؛ أي معايرته ليقرأ 500.0 g للكتلة المعيارية.', '["الصفر مضبوط مسبقًا؛ والمشكلة في القراءة عند الكتلة المعتمدة.","","القيمة المقبولة هي المعتمدة 500.0 g، أما 497.0 g فقراءة جهاز غير مضبوط.","تغيير الكتلة لا يصحح الميزان؛ فالمطلوب أن يعطي الميزان القيمة المعتمدة للكتلة نفسها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-18T12:34:59.077Z"}'::jsonb),
('mcq', 5, 3, 'الضبط اتفاق القراءة مع القيمة المقبولة؛ فعند قياس كمية قيمتها معتمدة يمكن معرفة هل يعطي الجهاز القيمة الصحيحة، ثم يُعاير حتى يعطيها.', '["الكمية المعتمدة ليست بالضرورة صغيرة؛ والمهم أن قيمتها معلومة بدقة.","اختلاف زاوية النظر خطأ في طريقة القراءة، ولا علاقة له بالكمية المقيسة.","الجهاز يقيس أي كمية؛ لكن المعايرة تحتاج قيمة معلومة للمقارنة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-18T12:34:59.078Z"}'::jsonb),
('mcq', 6, 0, 'تتم معايرة النقطتين أولًا بمعايرة صفر الجهاز، ثم بمعايرته بحيث يعطي قيمة مضبوطة عند قياس كمية ذات قيمة معتمدة.', '["","الترتيب معكوس؛ فالمعايرة تبدأ بالصفر أولًا.","الكتل المجهولة لا تصلح للمعايرة لأن قيمتها غير معتمدة.","تكرار القراءة لجسم مجهول يبين الدقة ولا يختبر الضبط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-18T12:34:59.078Z"}'::jsonb),
('mcq', 7, 1, 'معايرة النقطتين تحتاج نقطتين: الصفر، ثم قيمة معتمدة. الصفر مضبوط هنا، لكن القراءة 103.4 g لا تتفق مع 100.0 g؛ فيلزم إجراء الخطوة الثانية.', '["ضبط الصفر وحده لا يكفي؛ فالقراءة عند الكتلة المعتمدة تختلف بمقدار 3.4 g.","","قيمة الكتلة المعتمدة قاسها خبراء؛ والخطأ في الميزان لا في الكتلة.","القراءة رقمية ثابتة، والفرق ناتج عن عدم معايرة الجهاز على القيمة المعتمدة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-18T12:34:59.078Z"}'::jsonb),
('essay', 1, null::int, null, null, 'معايرة النقطتين هي الطريقة الشائعة لاختبار الضبط في الجهاز. تتم أولًا بمعايرة صفر الجهاز (أن يقرأ صفرًا عند عدم وجود كمية مقيسة)، ثم بمعايرة الجهاز بحيث يعطي قيمة مضبوطة وصحيحة عندما يقيس كمية ذات قيمة معتمدة. والغرض منها جعل قراءات الجهاز متفقة مع القيم المقبولة.', '["معايرة النقطتين طريقة لاختبار الضبط","الخطوة الأولى: معايرة الصفر","الخطوة الثانية: المعايرة بكمية ذات قيمة معتمدة","الغرض: اتفاق القراءات مع القيم المقبولة"]'::jsonb, '[]'::jsonb, '[{"element":"المفهوم","marks":1},{"element":"الخطوة الأولى","marks":1},{"element":"الخطوة الثانية","marks":1},{"element":"الغرض","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"توضيح كامل بالخطوتين والغرض"},{"level":"2–3 درجات","description":"ذكر الخطوتين دون الغرض أو العكس"},{"level":"1 درجة","description":"ذكر خطوة واحدة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عكس ترتيب الخطوتين","الاكتفاء بمعايرة الصفر","ربط المعايرة بالدقة بدل الضبط"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-11-18T12:34:59.078Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) في الخطوة الأولى تكون الكفة فارغة ويُعاير الصفر حتى يقرأ الميزان 0.0 g. في الخطوة الثانية تُوضع كتلة معيارية معتمدة قيمتها 200.0 g ويُعاير الميزان حتى يقرأ 200.0 g. (ب) لأن الميزان قد يقرأ الصفر صحيحًا ومع ذلك يعطي قراءات غير صحيحة للكتل الأخرى؛ فالخطوة الثانية تتحقق من أن الميزان يعطي القيمة المعتمدة عند قياس كمية معلومة.', '["الخطوة الأولى: معايرة الصفر والكفة فارغة","الخطوة الثانية: المعايرة على كتلة معتمدة 200.0 g","الصفر الصحيح لا يضمن صحة القراءات الأخرى"]'::jsonb, '[]'::jsonb, '[{"element":"وصف الخطوة الأولى","marks":1},{"element":"وصف الخطوة الثانية","marks":1},{"element":"تعليل الحاجة إلى نقطتين","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"وصف صحيح للخطوتين مع تعليل واضح"},{"level":"2–3 درجات","description":"وصف صحيح مع تعليل ناقص"},{"level":"1 درجة","description":"وصف خطوة واحدة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ الخطوة الثانية مجرد تكرار للقياس","إغفال أن قيمة الكتلة المعيارية معتمدة","الظن أن ضبط الصفر يكفي"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (39%)"}],"at":"2026-11-18T12:34:59.078Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) تحققت الخطوة الأولى (الصفر مضبوط)، ولم تتحقق الثانية لأن الميزان لا يعطي القيمة المعتمدة. (ب) مقدار الخطأ = $250.0 - 248.0 = 2.0\ \text{g}$ (القراءة أقل من القيمة المعتمدة). (ج) يجب أن يعاير الميزان حتى يقرأ 250.0 g عند وضع الكتلة المعيارية؛ لأن قياساته للكتل المجهولة ستكون غير مضبوطة ما لم تتفق قراءته مع القيمة المعتمدة.', '["الخطوة الأولى متحققة","الخطوة الثانية غير متحققة","الخطأ 2.0 g","معايرة الميزان ليقرأ 250.0 g","التعليل بالضبط"]'::jsonb, '["الخطأ = القيمة المعتمدة ناقص القراءة = $250.0 - 248.0 = 2.0\\ \\text{g}$"]'::jsonb, '[{"element":"تحديد الخطوة المتحققة وغير المتحققة","marks":2},{"element":"حساب الخطأ","marks":1},{"element":"الإجراء","marks":1},{"element":"التعليل","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة صحيحة"},{"level":"3–4 درجات","description":"إجابة صحيحة مع نقص في التعليل أو خطأ في الحساب"},{"level":"1–2 درجة","description":"تحديد صحيح للخطوتين فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الحكم بأن الميزان مضبوط لأنه يقرأ صفرًا","اقتراح تصحيح الكتلة المعيارية بدل الميزان","خطأ في حساب الفرق"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-18T12:34:59.079Z"}'::jsonb)
