('mcq', 2, 'يبين المنحنى الآتي قراءة ميزان لكتلة معتمدة خلال أربعة أشهر بعد معايرته. ماذا تستنتج؟', null, '[{"src":"qimg/phys1/c1l2-cal-drift.svg","alt":"منحنى نقاط موصولة: المحور الأفقي «الزمن منذ آخر معايرة (شهر)» من 0 إلى 4، والمحور الرأسي «قراءة الميزان (g)» من 99.5 إلى 102 بتدريج 0.5. قراءات الميزان لكتلة معتمدة: عند الشهر 0 تساوي 100.0 g، وعند الشهر 1 تساوي 100.4 g، وعند الشهر 2 تساوي 100.9 g، وعند الشهر 3 تساوي 101.3 g، وعند الشهر 4 تساوي 101.8 g. خط أخضر أفقي متقطع عند 100.0 g مكتوب عليه «القيمة المعتمدة»."}]'::jsonb, '["يزداد ضبط الميزان مع الزمن لأن قراءاته تزداد","تغيرت كتلة الجسم المعتمد مع الزمن","يفقد الميزان ضبطه تدريجيًّا فيلزم ضبطه دوريًّا","لا يحتاج الميزان إلى معايرة لأن قراءاته تتغير ببطء"]'::jsonb, 'فهم', 'تفسير منحنى', 'متوسط', 'الكتاب ص 20 — الضبط الدوري للأجهزة'),
('mcq', 3, 'يبين المنحنى الآتي قراءة ميزان لكتلة معتمدة بعد معايرته. إذا كان المختبر لا يقبل أن يزيد الفرق بين القراءة والقيمة المعتمدة على 1.0 g، ففي أيّ شهر تجاوز الفرق هذا الحد أول مرة؟', null, '[{"src":"qimg/phys1/c1l2-cal-drift2.svg","alt":"منحنى نقاط موصولة: المحور الأفقي «الزمن منذ آخر معايرة (شهر)» من 0 إلى 4، والمحور الرأسي «قراءة الميزان (g)» من 99.5 إلى 102 بتدريج 0.5. قراءات الميزان لكتلة معتمدة: عند الشهر 0 تساوي 100.0 g، وعند الشهر 1 تساوي 100.4 g، وعند الشهر 2 تساوي 100.9 g، وعند الشهر 3 تساوي 101.3 g، وعند الشهر 4 تساوي 101.8 g. خط أخضر أفقي متقطع عند 100.0 g مكتوب عليه «القيمة المعتمدة»."}]'::jsonb, '["الشهر الأول","الشهر الثاني","الشهر الرابع","الشهر الثالث"]'::jsonb, 'تطبيق', 'قراءة منحنى وتحليل', 'متوسط', 'الكتاب ص 20 — الضبط الدوري للأجهزة'),
('mcq', 4, 'عُوير ميزان في بداية العام فأعطى قراءات مضبوطة. لماذا لا يُضمن بقاء قراءاته مضبوطة بعد أشهر من الاستخدام؟', null, null, '["لأن ضبط الجهاز قد يتغير مع الزمن والاستخدام","لأن القيم المقبولة للكميات تتغير من شهر إلى آخر","لأن دقة الميزان تزداد مع كثرة الاستخدام","لأن الطلاب يقرؤون الشاشة الرقمية بزوايا مختلفة"]'::jsonb, 'فهم', 'تعليل', 'سهل', 'الكتاب ص 20 — الضبط الدوري للأجهزة'),
('mcq', 5, 'ما النتيجة المتوقعة لإهمال الضبط الدوري لميزان في المختبر مدة طويلة؟', null, null, '["تصبح قياساته متفرقة فقط دون أن يتأثر ضبطها","قد تبتعد قياساته عن القيم المقبولة دون أن يُلاحظ ذلك","يزداد أصغر تدريج يعرضه الميزان","لا يتأثر لأن الموازين الرقمية لا تحتاج إلى معايرة"]'::jsonb, 'فهم', 'استنتاج أثر', 'صعب', 'الكتاب ص 20 — الضبط الدوري للأجهزة'),
('mcq', 6, 'قاس مختبران كتلة العينة نفسها؛ الأول يعاير موازينه شهريًّا، والثاني لم يعاير موازينه منذ سنوات، فاتفقت نتيجة الأول مع القيمة المعتمدة واختلفت نتيجة الثاني عنها. ما التفسير الأنسب؟', null, null, '["موازين المختبر الثاني أكثر دقة من موازين الأول فأظهرت فرقًا أكبر","العينة تغيرت كتلتها عند نقلها إلى المختبر الثاني","موازين المختبر الثاني فقدت ضبطها لعدم معايرتها","القيمة المعتمدة تصلح للمختبر الأول فقط"]'::jsonb, 'فهم', 'تفسير موقف', 'متوسط', 'الكتاب ص 20 — الضبط الدوري للأجهزة'),
('mcq', 7, 'أعاد طالب قياس كتلة جسم عشر مرات بميزان لم يُعاير منذ مدة طويلة، فحصل على قراءات متطابقة تقريبًا. لماذا لا يغني ذلك عن معايرة الميزان؟', null, null, '["لأن تكرار القياس يزيد خطأ الميزان في كل مرة","لأن تكرار القياس يغيّر القيمة المقبولة للكتلة","لأن تكرار القياس عشر مرات يكشف خطأ الضبط ويصححه تلقائيًّا دون معايرة","لأن التكرار يبين الدقة ولا يكشف خطأ الضبط"]'::jsonb, 'تحليل', 'تعليل', 'صعب', 'الكتاب ص 19–20 — الدقة والضبط والضبط الدوري'),
('essay', 1, 'علّل: من الضروري إجراء الضبط الدوري لأجهزة القياس في المختبر، ومنها الموازين والجلفانومترات. ثم اذكر الطريقة المستخدمة في هذا الضبط.', null, null, null, 'فهم', 'تعليل', 'سهل', 'الكتاب ص 20 — الضبط الدوري للأجهزة'),
('essay', 2, 'يبين المنحنى الآتي قراءة ميزان لكتلة معتمدة خلال أربعة أشهر بعد آخر معايرة. (أ) صف كيف تغيرت قراءة الميزان مع الزمن. (ب) احسب الفرق بين قراءته والقيمة المعتمدة بعد أربعة أشهر. (ج) استخدم المنحنى لتعليل ضرورة الضبط الدوري للموازين.', null, '[{"src":"qimg/phys1/c1l2-cal-drift3.svg","alt":"منحنى نقاط موصولة: المحور الأفقي «الزمن منذ آخر معايرة (شهر)» من 0 إلى 4، والمحور الرأسي «قراءة الميزان (g)» من 99.5 إلى 102 بتدريج 0.5. قراءات الميزان لكتلة معتمدة: عند الشهر 0 تساوي 100.0 g، وعند الشهر 1 تساوي 100.4 g، وعند الشهر 2 تساوي 100.9 g، وعند الشهر 3 تساوي 101.3 g، وعند الشهر 4 تساوي 101.8 g. خط أخضر أفقي متقطع عند 100.0 g مكتوب عليه «القيمة المعتمدة»."}]'::jsonb, null, 'تحليل', 'تفسير منحنى وتعليل', 'متوسط', 'الكتاب ص 20 — الضبط الدوري للأجهزة'),
('essay', 3, 'قال طالب: «ميزاني يعطي القراءة نفسها كلما وزنت العينة نفسها، إذن لا يحتاج إلى ضبط دوري». قوّم هذه العبارة، ووضّح كيف يتحقق الطالب من حاجة ميزانه إلى المعايرة.', null, null, null, 'تقويم', 'تقويم عبارة', 'صعب', 'الكتاب ص 19–20 — الدقة والضبط والضبط الدوري')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'P1-C1-L2-O15') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 1, 'الضبط الدوري يتحقق من أن الجهاز ما زال يعطي قيمًا مضبوطة متفقة مع القيم المعتمدة، فتبقى القياسات به مضبوطة.', '["المعايرة لا تغير تدريجات الجهاز ولا دقته، بل تتحقق من اتفاق قراءاته مع القيم المعتمدة.","","اختلاف زاوية النظر خطأ شخصي يُتجنب بطريقة القراءة، لا بمعايرة الجهاز.","تحويل الوحدات يتم بمعاملات التحويل، ولا علاقة له بالمعايرة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (37%)"}],"at":"2026-11-18T12:34:59.079Z"}'::jsonb),
('mcq', 2, 2, 'القيمة المعتمدة ثابتة 100.0 g، وقراءة الميزان ارتفعت من 100.0 g إلى 101.8 g؛ أي إن الميزان يفقد ضبطه مع الزمن، وهذا يبرر الضبط الدوري.', '["ازدياد القراءة يبعدها عن القيمة المعتمدة 100.0 g، فيقل الضبط.","الكتلة المعتمدة ثابتة القيمة، والتغير في قراءة الميزان.","","التغير البطيء يتراكم حتى يصل الفرق إلى 1.8 g بعد أربعة أشهر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-11-18T12:34:59.079Z"}'::jsonb),
('mcq', 3, 3, 'الفروق: الشهر 1 → 0.4 g، الشهر 2 → 0.9 g، الشهر 3 → 1.3 g؛ فأول تجاوز للحد كان في الشهر الثالث، أي يجب إعادة المعايرة قبله.', '["الفرق في الشهر الأول 0.4 g فقط، وهو أقل من 1.0 g.","الفرق في الشهر الثاني 0.9 g، ولم يتجاوز 1.0 g بعد.","الفرق تجاوز 1.0 g قبل ذلك؛ ففي الشهر الثالث بلغ 1.3 g.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-11-18T12:34:59.080Z"}'::jsonb),
('mcq', 4, 0, 'الجهاز المضبوط اليوم قد يفقد ضبطه مع مرور الزمن والاستخدام، لذا من الضروري إجراء الضبط الدوري لأجهزة المختبر.', '["","القيم المقبولة معتمدة ثابتة؛ والذي يتغير هو أداء الجهاز.","الاستخدام لا يصغّر أصغر تدريج في الجهاز، فلا تزداد دقته.","القراءة الرقمية لا تتأثر بزاوية النظر، والمشكلة في ضبط الجهاز نفسه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-18T12:34:59.080Z"}'::jsonb),
('mcq', 5, 1, 'من دون الضبط الدوري قد تبتعد قياسات الميزان عن القيم المعتمدة، فتصبح القياسات غير مضبوطة، وقد تبقى متقاربة فلا يُكتشف الخطأ بسهولة.', '["فقدان المعايرة يُبعد القراءات عن القيم المقبولة، أي يؤثر في الضبط.","","أصغر تدريج صفة ثابتة في الجهاز لا تتغير بإهمال المعايرة.","الموازين من الأجهزة التي يجب إجراء الضبط الدوري لها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-18T12:34:59.080Z"}'::jsonb),
('mcq', 6, 2, 'موازين المختبر الثاني فقدت ضبطها لعدم معايرتها؛ فالمختبر الذي يعاير موازينه دوريًّا تبقى قراءاته متفقة مع القيم المعتمدة، أما الموازين غير المعايرة فقد تبتعد قراءاتها عنها.', '["الدقة لا تجعل النتيجة تبتعد عن القيمة المعتمدة؛ الابتعاد يدل على ضعف الضبط.","العينة نفسها، والفرق المرتبط بالمعايرة هو التفسير المنسجم مع المعطيات.","","القيمة المعتمدة واحدة لجميع المختبرات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-18T12:34:59.080Z"}'::jsonb),
('mcq', 7, 3, 'التكرار يبين الدقة ولا يكشف خطأ الضبط: تطابق القراءات يدل على الدقة؛ أما الضبط فيُختبر بمقارنة القراءة بقيمة معتمدة، وهذا ما تفعله المعايرة الدورية.', '["التكرار لا يزيد خطأ الجهاز؛ لكنه لا يكشف خطأ الضبط.","القيمة المقبولة معتمدة ولا تتأثر بعدد مرات القياس.","لو كان التكرار يصحح الضبط لأغنى عن المعايرة؛ لكنه لا يقارن بقيمة معتمدة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-18T12:34:59.080Z"}'::jsonb),
('essay', 1, null::int, null, null, 'لأن قراءات الأجهزة قد تبتعد مع الزمن والاستخدام عن القيم المقبولة، فتصبح القياسات غير مضبوطة؛ والضبط الدوري يضمن بقاء قراءاتها متفقة مع القيم المعتمدة. ويتم ذلك بمعايرة النقطتين: معايرة صفر الجهاز، ثم معايرته ليعطي قيمة مضبوطة عند قياس كمية ذات قيمة معتمدة.', '["القراءات قد تبتعد مع الزمن عن القيم المقبولة","الضبط الدوري يحافظ على اتفاق القراءات مع القيم المعتمدة","الطريقة: معايرة النقطتين"]'::jsonb, '[]'::jsonb, '[{"element":"التعليل","marks":2},{"element":"الطريقة","marks":1},{"element":"ذكر خطوتي المعايرة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تعليل صحيح مع ذكر الطريقة وخطوتيها"},{"level":"2–3 درجات","description":"تعليل صحيح مع نقص في الطريقة"},{"level":"1 درجة","description":"ذكر الطريقة دون تعليل"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["التعليل بأن الضبط الدوري يزيد دقة الأجهزة","إغفال القيم المعتمدة","الخلط بين المعايرة وتكرار القياس"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (37%)"}],"at":"2026-11-18T12:34:59.080Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) تزداد قراءة الميزان تدريجيًّا مع الزمن من 100.0 g إلى 101.8 g، مبتعدة عن القيمة المعتمدة 100.0 g. (ب) الفرق = $101.8 - 100.0 = 1.8\ \text{g}$. (ج) الميزان كان مضبوطًا بعد المعايرة مباشرة، ثم فقد ضبطه تدريجيًّا؛ فلو لم يُعاير دوريًّا لأعطى قياسات غير مضبوطة دون أن يشعر المستخدم، لذا يجب ضبطه دوريًّا.', '["تزداد القراءة تدريجيًّا مبتعدة عن 100.0 g","الفرق 1.8 g","الربط بين الانحراف وضرورة الضبط الدوري"]'::jsonb, '["الفرق بعد أربعة أشهر = $101.8 - 100.0 = 1.8\\ \\text{g}$"]'::jsonb, '[{"element":"الوصف","marks":1},{"element":"الحساب","marks":1},{"element":"التعليل","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"وصف وحساب صحيحان وتعليل مرتبط بالمنحنى"},{"level":"2–3 درجات","description":"خطأ في الحساب أو تعليل عام غير مرتبط بالمنحنى"},{"level":"1 درجة","description":"وصف صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["قراءة الفرق 101.8 g بدل 1.8 g","تفسير ازدياد القراءة بزيادة الضبط","عدم ربط الانحراف بالحاجة إلى المعايرة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-11-18T12:34:59.081Z"}'::jsonb),
('essay', 3, null::int, null, null, 'العبارة غير صحيحة؛ فتكرار القراءة نفسها يدل على الدقة (تقارب القراءات)، لكنه لا يدل على الضبط (اتفاقها مع القيمة المقبولة)، فقد يعطي الميزان القراءة الخاطئة نفسها في كل مرة إذا فقد معايرته. ليتحقق الطالب يضع على الميزان كتلة معيارية معتمدة بعد التأكد من أنه يقرأ صفرًا والكفة فارغة، فإن اختلفت القراءة عن القيمة المعتمدة فالميزان يحتاج إلى معايرة.', '["العبارة غير صحيحة","تكرار القراءة يدل على الدقة لا الضبط","القراءة قد تكون خاطئة باستمرار","التحقق بكتلة معيارية معتمدة بعد التحقق من الصفر"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم","marks":1},{"element":"التمييز بين الدقة والضبط","marks":1},{"element":"بيان إمكان الخطأ المتكرر","marks":1},{"element":"طريقة التحقق","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تقويم صحيح معلل مع طريقة تحقق مناسبة"},{"level":"2–3 درجات","description":"تقويم صحيح مع تعليل أو طريقة ناقصة"},{"level":"1 درجة","description":"حكم صحيح دون تعليل"},{"level":"صفر","description":"الموافقة على العبارة أو لا إجابة"}]'::jsonb, '["الموافقة على أن ثبات القراءة دليل على الضبط","اقتراح تكرار القياس للتحقق","إغفال الكتلة المعيارية المعتمدة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (4%)"}],"at":"2026-11-18T12:34:59.081Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
