from (values
('mcq', 1, 'كيف يجب أن تنظر إلى تدريج أداة القياس عند قراءته؟', null, null, '["بشكل مائل من جهة اليمين وبكلتا العينين","من أعلى بزاوية مائلة وبعين واحدة","عموديًّا على التدريج وبكلتا العينين","عموديًّا على التدريج وبعين واحدة"]'::jsonb, 'تذكر', 'تذكر إجراء', 'سهل', 'الكتاب ص 20 — تقنيات القياس الجيد (الشكل 1-12)'),
('mcq', 2, 'أيّ مما يأتي من تقنيات القياس الجيد؟', null, null, '["استخدام الأجهزة بطريقة صحيحة وبحذر وانتباه","قراءة التدريج بسرعة من أي زاوية لتوفير الوقت","الاكتفاء بقراءة واحدة دون الانتباه لأسباب الخطأ","استخدام أي أداة متاحة بغض النظر عن طريقة استعمالها"]'::jsonb, 'فهم', 'تمييز إجراء صحيح', 'سهل', 'الكتاب ص 20 — تقنيات القياس الجيد (الشكل 1-12)'),
('mcq', 3, 'في الشكل الآتي يقرأ طالب موضع مؤشر فوق تدريج من موضعين للعين. أيّ الموضعين يمثل الطريقة الصحيحة، وما القراءة الصحيحة؟', null, '[{"src":"qimg/phys1/c1l2-plx-o16.svg","alt":"منظر جانبي: تدريج أفقي بالسنتيمتر مرقّم من 1 إلى 5 بتدريجات صغيرة كل 0.1 cm، ومؤشر رأسي مثبّت فوق التدريج بمسافة صغيرة وطرفه السفلي فوق العلامة 3 تمامًا. العين 1 فوق المؤشر مباشرة تنظر رأسيًّا إلى أسفل، وخط نظرها المتقطع يمر بطرف المؤشر ويصل إلى العلامة 3.0 cm. العين 2 أعلى يمين المؤشر تنظر بشكل مائل، وخط نظرها المتقطع يمر بطرف المؤشر ويمتد حتى يصل إلى التدريج عند 2.6 cm."}]'::jsonb, '["الموضع 2، والقراءة 2.6 cm","الموضع 1، والقراءة 2.6 cm","الموضع 1، والقراءة 3.0 cm","الموضع 2، والقراءة 3.0 cm"]'::jsonb, 'فهم', 'تطبيق إجراء على شكل', 'متوسط', 'الكتاب ص 20 — تقنيات القياس الجيد (الشكل 1-12)'),
('mcq', 4, 'قاس طالب طول قلم بالمسطرة المبينة في الشكل الآتي، وسجّل 4.0 cm. ما الخطأ في طريقته؟', null, '[{"src":"qimg/phys1/c1l2-rul-edge2.svg","alt":"مسطرة خشبية تدريجها بالسنتيمتر من 0 إلى 6، وأصغر تدريج فيها 0.5 cm. علامة الصفر لا تقع عند حافة المسطرة اليسرى بل بعدها بمسافة 0.5 cm (تدريج صغير واحد). فوق المسطرة قلم، طرفه الأيسر عند حافة المسطرة اليسرى تمامًا، ورأسه المدبب عند العلامة 4 تمامًا."}]'::jsonb, '["نظر إلى التدريج عموديًّا بعين واحدة","وضع طرف القلم عند الحافة لا عند الصفر","استخدم مسطرة أصغر تدريج فيها 0.5 cm وهي غير صالحة","لم يكرر القياس عدة مرات ثم يحسب متوسط القراءات"]'::jsonb, 'فهم', 'تشخيص خطأ إجرائي', 'متوسط', 'الكتاب ص 20–21 — تقنيات القياس الجيد (سؤال المراجعة 14)'),
('mcq', 5, 'لماذا يُنصح بقراءة التدريج بالنظر إليه عموديًّا وبعين واحدة؟', null, null, '["لزيادة دقة الأداة بتصغير قيمة أصغر تدريج فيها","لأن النظر بالعينين معًا يجعل القراءة مضاعفة","لتقليل الزمن اللازم لأخذ القراءة","لتجنب اختلاف زاوية النظر فتكون القراءة أضبط"]'::jsonb, 'فهم', 'تعليل إجراء', 'متوسط', 'الكتاب ص 20 — تقنيات القياس الجيد (الشكل 1-12)'),
('mcq', 6, 'أيّ الإجراءات الآتية يمثل استخدامًا صحيحًا لميزان رقمي عند قياس كتلة جسم؟', null, null, '["التأكد من أن الميزان يقرأ صفرًا والكفة فارغة قبل وضع الجسم","وضع الجسم على الكفة مباشرة دون النظر إلى قراءة الكفة الفارغة","الضغط باليد على الكفة لتثبيت القراءة","تسجيل أول رقم يظهر قبل أن تستقر القراءة"]'::jsonb, 'فهم', 'تمييز إجراء صحيح', 'صعب', 'الكتاب ص 20 — تقنيات القياس الجيد ومعايرة الصفر'),
('mcq', 7, 'قاس أربعة طلاب طول قلم حبر بمسطرة يبدأ صفرها عند حافتها. أيّ الطلاب اتبع الطريقة الصحيحة؟', null, null, '["وضع طرف القلم عند الصفر، وقرأ موضع طرفه الآخر بعد أن حرّك رأسه إلى اليسار","وضع طرف القلم عند العلامة 1 cm، وسجّل قراءة طرفه الآخر طولًا للقلم","وضع طرف القلم عند الصفر، ونظر عموديًّا بعين واحدة إلى موضع طرفه الآخر","وضع القلم مائلًا على المسطرة، ونظر عموديًّا إلى طرفه الآخر"]'::jsonb, 'تحليل', 'مقارنة إجراءات', 'صعب', 'الكتاب ص 20 — تقنيات القياس الجيد (الشكل 1-12)'),
('essay', 1, 'صف الطريقة الصحيحة في القياس كي تصل إلى مستوى الضبط والدقة اللذين يسمح بهما الجهاز.', null, null, null, 'فهم', 'وصف إجراء', 'سهل', 'الكتاب ص 20 — تقنيات القياس الجيد (الشكل 1-12)'),
('essay', 2, 'صف خطوات قياس طول قلم حبر بمسطرة مترية قياسًا صحيحًا، بحيث تكون القراءة مضبوطة قدر الإمكان، مع ذكر سبب كل خطوة.', null, null, null, 'فهم', 'وصف إجراء', 'متوسط', 'الكتاب ص 20–21 — تقنيات القياس الجيد'),
('essay', 3, 'قاس طالب طول قلم بالمسطرة المبينة في الشكل الآتي، علمًا بأن أصغر تدريج فيها 0.5 cm. (أ) ما القراءة التي يسجلها الطالب؟ وما الطول الحقيقي للقلم؟ (ب) صف الطريقة الصحيحة لقياس طول القلم بهذه المسطرة.', null, '[{"src":"qimg/phys1/c1l2-rul-edge3.svg","alt":"مسطرة خشبية تدريجها بالسنتيمتر من 0 إلى 6، وأصغر تدريج فيها 0.5 cm. علامة الصفر لا تقع عند حافة المسطرة اليسرى بل بعدها بمسافة 0.5 cm (تدريج صغير واحد). فوق المسطرة قلم، طرفه الأيسر عند حافة المسطرة اليسرى تمامًا، ورأسه المدبب عند العلامة 4 تمامًا."}]'::jsonb, null, 'تطبيق', 'تشخيص خطأ وتصحيح إجراء', 'صعب', 'الكتاب ص 20–21 — تقنيات القياس الجيد (سؤال المراجعة 14)')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
