insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 3, 'يجب أن تُقرأ التدريجات بالنظر عموديًّا وبعين واحدة لتجنب اختلاف زاوية النظر.', '["النظر المائل يسبب اختلاف زاوية النظر فتكون القراءة غير مضبوطة.","النظر بزاوية مائلة يعطي قراءة مختلفة حتى لو كان بعين واحدة.","يجب أن تُقرأ التدريجات بالنظر عموديًّا وبعين واحدة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-18T12:34:59.081Z"}'::jsonb),
('mcq', 2, 0, 'لضمان الوصول إلى الضبط والدقة المطلوبين يجب أن تُستخدم الأجهزة بطريقة صحيحة، وأن تتم القياسات بحذر وانتباه لتجنب أسباب الخطأ.', '["","القراءة من زاوية مائلة تسبب اختلاف زاوية النظر.","يجب إجراء القياس بحذر وانتباه لتجنب أسباب الخطأ.","يجب استخدام الأجهزة بطريقة صحيحة لضمان الضبط والدقة المطلوبين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-18T12:34:59.081Z"}'::jsonb),
('mcq', 3, 2, 'الموضع 1 عمودي على التدريج فوق المؤشر مباشرة، فيعطي القراءة الصحيحة 3.0 cm؛ أما الموضع 2 فمائل ويعطي 2.6 cm.', '["الموضع 2 مائل؛ فخط نظره يمتد عبر المؤشر إلى قيمة غير صحيحة.","الموضع 1 صحيح، لكن خط نظره العمودي يصل إلى 3.0 cm لا 2.6 cm.","","القراءة 3.0 cm صحيحة لكنها تُؤخذ من الموضع العمودي 1 لا المائل 2."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-18T12:34:59.082Z"}'::jsonb),
('mcq', 4, 1, 'صفر هذه المسطرة لا يقع عند حافتها؛ فوضع طرف القلم عند الحافة يجعل القراءة أقل من الطول الحقيقي. يجب وضع طرف الجسم عند علامة الصفر.', '["هذه هي الطريقة الصحيحة لقراءة التدريج، وليست خطأ.","","المسطرة صالحة للقياس، وأصغر تدريج يحدد دقة القياس فقط.","التكرار بالطريقة الخاطئة نفسها يعطي الخطأ نفسه؛ والخطأ في موضع بداية القياس."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-11-18T12:34:59.082Z"}'::jsonb),
('mcq', 5, 3, 'النظر المائل يسبب اختلاف زاوية النظر فتنتج قيمة مختلفة وغير مضبوطة؛ أما النظر العمودي بعين واحدة فيعطي قراءة أضبط.', '["طريقة النظر لا تغيّر أصغر تدريج في الأداة.","النظر بالعينين لا يضاعف القراءة، لكنه قد يجعل خط النظر غير عمودي.","الغرض ضبط القراءة لا سرعتها.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-11-18T12:34:59.082Z"}'::jsonb),
('mcq', 6, 0, 'من استخدام الجهاز بطريقة صحيحة التأكد من أن الميزان يقرأ صفرًا والكفة فارغة قبل وضع الجسم، ثم إجراء القياس بحذر وانتباه.', '["","إذا لم يكن الصفر مضبوطًا ستكون جميع القراءات غير مضبوطة.","الضغط باليد يضيف قوة فتزداد القراءة عن الكتلة الحقيقية.","القياس بحذر وانتباه يعني انتظار استقرار القراءة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-11-18T12:34:59.082Z"}'::jsonb),
('mcq', 7, 2, 'الطريقة الصحيحة: طرف الجسم عند صفر التدريج والجسم موازٍ له، ثم قراءة الطرف الآخر بالنظر عموديًّا وبعين واحدة.', '["تحريك الرأس يجعل النظر مائلًا فيحدث اختلاف زاوية النظر.","القراءة عند الطرف الآخر تزيد على الطول الحقيقي بمقدار 1 cm.","","وضع القلم مائلًا لا يجعله موازيًا للتدريج، فتكون القراءة غير صحيحة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-18T12:34:59.082Z"}'::jsonb),
('essay', 1, null::int, null, null, 'يجب أن تُستخدم الأجهزة بطريقة صحيحة، وأن تتم القياسات بحذر وانتباه لتجنب أسباب الخطأ في القياس. ومن ذلك قراءة التدريجات بالنظر عموديًّا وبعين واحدة لتجنب اختلاف زاوية النظر، لأن القراءة المائلة تعطي قيمة مختلفة وغير مضبوطة.', '["استخدام الأجهزة بطريقة صحيحة","القياس بحذر وانتباه لتجنب أسباب الخطأ","قراءة التدريج عموديًّا وبعين واحدة","تجنب اختلاف زاوية النظر"]'::jsonb, '[]'::jsonb, '[{"element":"الاستخدام الصحيح","marks":1},{"element":"الحذر والانتباه","marks":1},{"element":"النظر العمودي بعين واحدة","marks":1},{"element":"ذكر سبب ذلك","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"وصف كامل بالعناصر الأربعة"},{"level":"2–3 درجات","description":"إغفال عنصر أو عنصرين"},{"level":"1 درجة","description":"ذكر عنصر واحد"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الاكتفاء بذكر تكرار القياس","إغفال النظر بعين واحدة","عدم ربط النظر العمودي بتجنب اختلاف زاوية النظر"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-18T12:34:59.082Z"}'::jsonb),
('essay', 2, null::int, null, null, '1) أتحقق من موضع صفر المسطرة (هل يبدأ عند الحافة أم بعدها)؛ لأن بعض المساطر لا يبدأ صفرها عند الحافة. 2) أضع القلم موازيًا للتدريج وملاصقًا له، وطرفه عند علامة الصفر تمامًا؛ حتى تساوي القراءة الطول الحقيقي. 3) أنظر إلى الطرف الآخر عموديًّا على التدريج وبعين واحدة؛ لتجنب اختلاف زاوية النظر. 4) أسجل القراءة بحذر وانتباه مع وحدتها؛ لتجنب أخطاء التسجيل.', '["التحقق من موضع الصفر","وضع طرف القلم عند الصفر موازيًا للتدريج","النظر العمودي بعين واحدة","التسجيل بحذر مع الوحدة","ذكر أسباب الخطوات"]'::jsonb, '[]'::jsonb, '[{"element":"خطوة الصفر","marks":1},{"element":"وضع القلم","marks":1},{"element":"طريقة النظر","marks":1},{"element":"التسجيل","marks":1},{"element":"الأسباب","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"خطوات كاملة مرتبة مع أسبابها"},{"level":"3–4 درجات","description":"خطوات صحيحة مع نقص في الأسباب أو خطوة واحدة"},{"level":"1–2 درجة","description":"ذكر خطوة أو خطوتين"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["افتراض أن الصفر يقع دائمًا عند حافة المسطرة","إغفال النظر العمودي","وضع القلم مائلًا على التدريج"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-18T12:34:59.082Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) يسجل الطالب 4.0 cm لأن رأس القلم عند العلامة 4، لكن طرف القلم عند حافة المسطرة التي تسبق الصفر بمسافة 0.5 cm؛ فالطول الحقيقي = $4.0 + 0.5 = 4.5\ \text{cm}$. (ب) يُحرَّك القلم حتى يقع طرفه عند علامة الصفر تمامًا لا عند الحافة، ويوضع موازيًا للتدريج، ثم يُقرأ موضع رأسه بالنظر عموديًّا وبعين واحدة.', '["القراءة المسجلة 4.0 cm","الطول الحقيقي 4.5 cm","وضع طرف القلم عند الصفر","النظر العمودي بعين واحدة"]'::jsonb, '["المسافة بين الحافة والصفر = 0.5 cm","الطول الحقيقي = $4.0 + 0.5 = 4.5\\ \\text{cm}$"]'::jsonb, '[{"element":"القراءة المسجلة","marks":1},{"element":"الطول الحقيقي","marks":1},{"element":"الطريقة الصحيحة","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة"},{"level":"2–3 درجات","description":"خطأ في الطول الحقيقي أو نقص في وصف الطريقة"},{"level":"1 درجة","description":"ذكر القراءة المسجلة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["طرح 0.5 cm بدل إضافتها (3.5 cm)","عدّ 4.0 cm الطول الحقيقي","إغفال وضع طرف الجسم عند الصفر"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-11-18T12:34:59.083Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'P1-C1-L2-O16') and x.type = v.type and x.number = v.number
on conflict (question_id) do nothing;

insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'P1-C1-L2-O17'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'قاست أربع مجموعات تسارع الجاذبية الأرضية، ومُثّلت نتائجها في الرسم الآتي مع القيمة المقبولة. أيّ المجموعات نتيجتها أكثر ضبطًا؟', null, '[{"src":"qimg/phys1/c1l2-eb-g.svg","alt":"رسم بياني بأعمدة خطأ: المحور الأفقي «المجموعة» وعليه أربع مجموعات A وB وC وD، والمحور الرأسي «تسارع الجاذبية (m/s²)» من 9.4 إلى 10.1 بتدريج 0.1. خط أخضر أفقي متقطع عند 9.80 مكتوب عليه «القيمة المقبولة». نتيجة المجموعة A تساوي 9.62 بعمود خطأ 0.03 في كل اتجاه، ونتيجة B تساوي 9.79 بعمود خطأ 0.04، ونتيجة C تساوي 9.92 بعمود خطأ 0.02، ونتيجة D تساوي 9.70 بعمود خطأ 0.25 (يمتد من 9.45 إلى 9.95)."}]'::jsonb, '["المجموعة B","المجموعة C","المجموعة D","المجموعة A"]'::jsonb, 'تحليل', 'تحديد الأكثر ضبطًا من رسم', 'متوسط', 'الكتاب ص 19–20 — الضبط والقيمة المقبولة'),
('mcq', 2, 'قاس طالبان سرعة الضوء، فحصل الأول على $(3.001 \pm 0.001) \times 10^8\ \text{m/s}$، والثاني على $(2.999 \pm 0.006) \times 10^8\ \text{m/s}$. أيّ القياسين أكثر ضبطًا علمًا بأن القيمة المعيارية لسرعة الضوء $2.99792458 \times 10^8\ \text{m/s}$؟', null, null, '["قياس الأول؛ لأن هامش خطئه أصغر","قياس الأول؛ لأن قيمته أكبر من القيمة المعيارية","لا يمكن المقارنة لأن هامشي الخطأ مختلفان","قياس الثاني؛ لأنه أقرب إلى القيمة المعيارية"]'::jsonb, 'تحليل', 'تحديد الأكثر ضبطًا', 'صعب', 'الكتاب ص 26 — السؤال 30b'),
('mcq', 3, 'قِيس طول قضيب قيمته المقبولة 25.0 cm بأربع مساطر مختلفة، فكانت النتائج كما في الجدول الآتي. أيّ المساطر أعطت القياس الأكثر ضبطًا؟', '{"headers":["المسطرة","الطول المقيس (cm)"],"rows":[["1","24.2"],["2","25.1"],["3","25.6"],["4","24.7"]]}'::jsonb, null, '["المسطرة 1","المسطرة 2","المسطرة 3","المسطرة 4"]'::jsonb, 'تحليل', 'تحديد الأكثر ضبطًا من جدول', 'سهل', 'الكتاب ص 20 — الضبط'),
('mcq', 4, 'قاس طالب طول قلم بالمسطرة المبينة في الشكل الآتي، ووضع طرف القلم عند حافة المسطرة فسجّل 4.0 cm. علمًا بأن صفر المسطرة يبعد 0.5 cm عن حافتها، ما الطول الحقيقي للقلم؟ وكيف يؤثر ذلك في ضبط قياسه؟', null, '[{"src":"qimg/phys1/c1l2-rul-edge.svg","alt":"مسطرة خشبية تدريجها بالسنتيمتر من 0 إلى 6، وأصغر تدريج فيها 0.5 cm. علامة الصفر لا تقع عند حافة المسطرة اليسرى بل بعدها بمسافة 0.5 cm (تدريج صغير واحد). فوق المسطرة قلم، طرفه الأيسر عند حافة المسطرة اليسرى تمامًا، ورأسه المدبب عند العلامة 4 تمامًا."}]'::jsonb, '["3.5 cm، وقياسه أقل ضبطًا لأنه يزيد 0.5 cm","4.5 cm، ويتأثر قياسه في الدقة لا في الضبط","4.5 cm، وقياسه أقل ضبطًا لأنه ينقص 0.5 cm","4.0 cm، وقياسه مضبوط لأن رأس القلم عند تدريج"]'::jsonb, 'تحليل', 'تحليل أثر خطأ على الضبط', 'صعب', 'الكتاب ص 21 — سؤال المراجعة 14'),
('mcq', 5, 'قدّر عالمان عمر قطعة أثرية، فحصل العالم A على $(1530 \pm 20)$ سنة، وحصل العالم B على $(1490 \pm 30)$ سنة. إذا كان العمر المقبول للقطعة 1500 سنة، فأيّ العبارات الآتية صحيحة؟', null, null, '["قياس A أكثر ضبطًا لأن هامش خطئه أصغر","قياس B أكثر ضبطًا مع أن قياس A أكثر دقة","قياس A أكثر ضبطًا لأن قيمته أكبر","القياسان متساويان في الضبط لأن الفرق بينهما 40 سنة"]'::jsonb, 'تحليل', 'تحديد الأكثر ضبطًا', 'متوسط', 'الكتاب ص 29 — السؤال 1 (بتعديل البيانات)'),
('mcq', 6, 'يبين الرسم الآتي نتائج ثلاثة طلاب في قياس زمن دورة بندول مع القيمة المقبولة. أيّ العبارات الآتية صحيحة؟', null, '[{"src":"qimg/phys1/c1l2-eb-pend.svg","alt":"رسم بياني بأعمدة خطأ: المحور الأفقي «الطالب» وعليه ثلاثة طلاب A وB وC، والمحور الرأسي «زمن الدورة (s)» من 1.80 إلى 2.20 بتدريج 0.05. خط أخضر أفقي متقطع عند 2.00 s مكتوب عليه «القيمة المقبولة». نتيجة A تساوي 2.10 s بعمود خطأ 0.01 s في كل اتجاه، ونتيجة B تساوي 1.99 s بعمود خطأ 0.08 s (يمتد من 1.91 إلى 2.07)، ونتيجة C تساوي 2.01 s بعمود خطأ 0.02 s."}]'::jsonb, '["نتيجة C أكثر ضبطًا من نتيجة A مع أن هامش خطأ A أصغر","نتيجة A أكثر النتائج ضبطًا لأن هامش خطئها أصغر","نتيجة B أقل ضبطًا من نتيجة A لأن هامش خطئها أكبر","النتائج الثلاث متساوية في الضبط لأنها قريبة من 2 s"]'::jsonb, 'تحليل', 'تحليل رسم بأعمدة خطأ', 'صعب', 'الكتاب ص 19–20 — الدقة والضبط'),
('mcq', 7, 'عند تحديد القياس الأكثر ضبطًا من بين عدة قياسات للكمية نفسها، أيّ القياسات نختار؟', null, null, '["الأصغر هامشًا للخطأ","المكتوب بأرقام معنوية أكثر","الذي تكررت قيمته أكثر","الأقرب إلى القيمة المقبولة"]'::jsonb, 'فهم', 'قاعدة تحديد الأكثر ضبطًا', 'سهل', 'الكتاب ص 20، 25 — الضبط'),
('essay', 1, 'قاس ثلاثة طلاب كثافة الماء، والقيمة المقبولة لها $1.00\ \text{g/cm}^3$، فكانت نتائجهم كما في الجدول الآتي. حدّد أيّ القياسات أكثر ضبطًا، ورتّبها من الأكثر إلى الأقل ضبطًا، مع التعليل.', '{"headers":["الطالب","الكثافة المقيسة ($\\text{g/cm}^3$)"],"rows":[["سارة","0.96"],["خالد","1.02"],["منى","1.07"]]}'::jsonb, null, null, 'تحليل', 'تحديد وترتيب الأكثر ضبطًا', 'سهل', 'الكتاب ص 20 — الضبط'),
('essay', 2, 'قاس أربعة طلاب كتلة جسم قيمتها المقبولة 50.0 g، ومُثّلت نتائجهم في الرسم الآتي. (أ) رتّب نتائج الطلاب من الأكثر ضبطًا إلى الأقل ضبطًا موضحًا حساباتك. (ب) هل تختلف نتائجهم في الدقة؟ وضّح.', null, '[{"src":"qimg/phys1/c1l2-eb-mass2.svg","alt":"رسم بياني بأعمدة خطأ: المحور الأفقي «الطالب» وعليه أربعة طلاب A وB وC وD، والمحور الرأسي «الكتلة (g)» من 47.5 إلى 52 بتدريج 0.5. خط أخضر أفقي متقطع عند 50.0 g مكتوب عليه «القيمة المقبولة». نتيجة الطالب A تساوي 48.6 g، ونتيجة B تساوي 50.1 g، ونتيجة C تساوي 51.2 g، ونتيجة D تساوي 49.0 g، ولكل منها عمود خطأ مقداره 0.2 g في كل اتجاه."}]'::jsonb, null, 'تحليل', 'ترتيب حسب الضبط من رسم', 'متوسط', 'الكتاب ص 19–20 — الدقة والضبط'),
('essay', 3, 'قيست درجة حرارة الماء المغلي عند الضغط الجوي المعياري (القيمة المقبولة $100.0\ ^\circ\text{C}$) بثلاثة مقاييس حرارة، وأُخذت بكل منها ثلاث قراءات كما في الجدول الآتي. (أ) احسب متوسط قراءات كل مقياس. (ب) أيّ المقاييس أعطى قياسًا أكثر ضبطًا؟ (ج) هل المقياس الأكثر ضبطًا هو الأكثر دقة أيضًا؟ وضّح.', '{"headers":["المقياس","القراءة 1 ($^\\circ\\text{C}$)","القراءة 2 ($^\\circ\\text{C}$)","القراءة 3 ($^\\circ\\text{C}$)"],"rows":[["1","98.0","98.1","98.0"],["2","99.4","100.6","100.1"],["3","101.5","101.4","101.6"]]}'::jsonb, null, null, 'تحليل', 'تحليل بيانات تجريبية', 'متوسط', 'الكتاب ص 19–20 — الدقة والضبط')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
