select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 0, 'الأكثر ضبطًا هي الأقرب إلى القيمة المقبولة $9.80\ \text{m/s}^2$: نتيجة B تساوي 9.79 فالفرق 0.01 فقط، وهو أصغر الفروق.', '["","هامش خطأ C هو الأصغر فهي الأكثر دقة، لكنها تبعد 0.12 m/s² عن القيمة المقبولة.","مدى D يشمل القيمة المقبولة بسبب هامش خطئها الكبير، لكن قيمتها 9.70 تبعد 0.10 m/s² عن 9.80.","نتيجة A (9.62) تبعد 0.18 m/s² عن القيمة المقبولة، وهي الأبعد."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-18T12:34:59.083Z"}'::jsonb),
('mcq', 2, 3, 'الفرق للأول $\approx 0.003 \times 10^8$، وللثاني $\approx 0.001 \times 10^8$؛ كما أن القيمة المعيارية تقع ضمن مدى الثاني (2.993 إلى 3.005) ولا تقع ضمن مدى الأول (3.000 إلى 3.002). فالثاني أكثر ضبطًا.', '["صغر هامش الخطأ يجعل قياس الأول أكثر دقة، لا أكثر ضبطًا.","كون القيمة أكبر لا يدل على الضبط؛ والمهم مقدار القرب من القيمة المعيارية.","المقارنة بالقيمة المعيارية ممكنة دائمًا، واختلاف هامش الخطأ يتعلق بالدقة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-18T12:34:59.084Z"}'::jsonb),
('mcq', 3, 1, 'الفروق عن 25.0 cm: المسطرة 1 → 0.8، المسطرة 2 → 0.1، المسطرة 3 → 0.6، المسطرة 4 → 0.3؛ فالمسطرة 2 الأكثر ضبطًا.', '["نتيجتها 24.2 cm تبعد 0.8 cm عن القيمة المقبولة.","","نتيجتها 25.6 cm تبعد 0.6 cm عن القيمة المقبولة.","نتيجتها 24.7 cm تبعد 0.3 cm، وهي أبعد من نتيجة المسطرة 2."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-18T12:34:59.084Z"}'::jsonb),
('mcq', 4, 2, 'المسافة من الحافة إلى الصفر 0.5 cm لم تُحسب، فالطول الحقيقي $4.0 + 0.5 = 4.5\ \text{cm}$، والقراءة المسجلة تبتعد عن القيمة الصحيحة فهي أقل ضبطًا.', '["طرح 0.5 cm بدل إضافتها؛ فالجزء بين الحافة والصفر جزء من طول القلم لم يُحسب.","الطول صحيح، لكن هذا الخطأ يُبعد القراءة عن القيمة الصحيحة فيؤثر في الضبط؛ أما الدقة فيحددها أصغر تدريج.","","وقوع الرأس عند تدريج لا يكفي؛ فبداية القلم ليست عند الصفر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-11-18T12:34:59.084Z"}'::jsonb),
('mcq', 5, 1, 'بُعد A عن 1500 هو 30 سنة، وبُعد B هو 10 سنوات؛ فـ B أكثر ضبطًا، والقيمة المقبولة تقع ضمن مداه (1460–1520) ولا تقع ضمن مدى A (1510–1550). أما هامش خطأ A الأصغر فيجعله أكثر دقة.', '["هامش الخطأ الأصغر يجعل A أكثر دقة، لكنه يبعد 30 سنة عن العمر المقبول مقابل 10 سنوات لـ B.","","كبر القيمة لا يدل على الضبط؛ المعيار هو القرب من القيمة المقبولة.","الفرق بين القياسين لا يحدد الضبط؛ بل بُعد كل منهما عن القيمة المقبولة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-18T12:34:59.084Z"}'::jsonb),
('mcq', 6, 0, 'بُعد النتائج عن 2.00 s: A → 0.10 s، B → 0.01 s، C → 0.01 s. إذن C (وكذلك B) أكثر ضبطًا من A، مع أن هامش خطأ A (0.01 s) أصغر من هامش C (0.02 s).', '["","هامش الخطأ الأصغر يدل على الدقة؛ ونتيجة A (2.10 s) هي الأبعد عن 2.00 s.","B تبعد 0.01 s فقط عن القيمة المقبولة، وA تبعد 0.10 s؛ فـ B أكثر ضبطًا من A.","A تبعد 0.10 s بينما B وC تبعد كل منهما 0.01 s، فليست متساوية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-18T12:34:59.085Z"}'::jsonb),
('mcq', 7, 3, 'الضبط اتفاق النتيجة مع القيمة المقبولة؛ فالقياس الأكثر ضبطًا هو الأقرب إليها.', '["الهامش الأصغر يدل على الدقة لا على الضبط.","كثرة الأرقام المعنوية لا تعني القرب من القيمة المقبولة.","تكرار القيمة يدل على تقارب القراءات (الدقة).",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-18T12:34:59.085Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الفروق عن القيمة المقبولة: سارة $|0.96 - 1.00| = 0.04$، وخالد $|1.02 - 1.00| = 0.02$، ومنى $|1.07 - 1.00| = 0.07$ (جميعها بوحدة $\text{g/cm}^3$). إذن قياس خالد الأكثر ضبطًا، والترتيب: خالد ثم سارة ثم منى؛ لأن الضبط يزداد كلما قلّ بُعد النتيجة عن القيمة المقبولة.', '["حساب الفروق الثلاثة","خالد الأكثر ضبطًا","الترتيب: خالد، سارة، منى","التعليل بالقرب من القيمة المقبولة"]'::jsonb, '["سارة: $|0.96 - 1.00| = 0.04\\ \\text{g/cm}^3$","خالد: $|1.02 - 1.00| = 0.02\\ \\text{g/cm}^3$","منى: $|1.07 - 1.00| = 0.07\\ \\text{g/cm}^3$","أصغر فرق ← أكثر ضبطًا"]'::jsonb, '[{"element":"الحسابات","marks":1},{"element":"تحديد الأكثر ضبطًا","marks":1},{"element":"الترتيب","marks":1},{"element":"التعليل","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة"},{"level":"2–3 درجات","description":"تحديد صحيح مع خطأ في الترتيب أو التعليل"},{"level":"1 درجة","description":"تحديد الأكثر ضبطًا دون حساب أو تعليل"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ القيمة الأكبر أكثر ضبطًا","إهمال القيمة المطلقة فيُعدّ الفرق السالب أصغر","الترتيب حسب القيم لا حسب الفروق"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-18T12:34:59.085Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) البُعد عن 50.0 g: A → $|48.6 - 50.0| = 1.4$، B → 0.1، C → 1.2، D → 1.0 (بوحدة g). الترتيب من الأكثر ضبطًا: B ثم D ثم C ثم A. (ب) لا تختلف؛ فهامش الخطأ واحد لجميع النتائج ($\pm 0.2\ \text{g}$)، لذا هي متساوية في الدقة وتختلف في الضبط فقط.', '["حساب الفروق الأربعة","الترتيب: B، D، C، A","الدقة متساوية لتساوي هامش الخطأ"]'::jsonb, '["A: $50.0 - 48.6 = 1.4\\ \\text{g}$","B: $50.1 - 50.0 = 0.1\\ \\text{g}$","C: $51.2 - 50.0 = 1.2\\ \\text{g}$","D: $50.0 - 49.0 = 1.0\\ \\text{g}$"]'::jsonb, '[{"element":"الحسابات","marks":2},{"element":"الترتيب","marks":1},{"element":"الحكم على الدقة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حسابات وترتيب وحكم صحيح"},{"level":"2–3 درجات","description":"خطأ في فرق واحد أو في الحكم على الدقة"},{"level":"1 درجة","description":"تحديد B الأكثر ضبطًا فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ترتيب C قبل A أو العكس دون حساب","الحكم بأن نتيجة B أكثر دقة لأنها أقرب","الخلط بين الدقة والضبط"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-18T12:34:59.086Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) المتوسطات: المقياس 1 ≈ $98.0\ ^\circ\text{C}$، والمقياس 2 ≈ $100.0\ ^\circ\text{C}$، والمقياس 3 = $101.5\ ^\circ\text{C}$. (ب) المقياس 2 أكثر ضبطًا لأن متوسطه يتفق مع القيمة المقبولة. (ج) لا؛ فقراءات المقياس 2 متباعدة (من 99.4 إلى 100.6)، بينما قراءات المقياس 1 متقاربة جدًّا (تختلف 0.1 فقط) فهو الأكثر دقة، لكنه الأقل ضبطًا لأن متوسطه يبعد $2.0\ ^\circ\text{C}$ عن القيمة المقبولة.', '["المتوسطات الثلاثة","المقياس 2 الأكثر ضبطًا","المقياس 1 الأكثر دقة (قراءاته متقاربة)","الأكثر ضبطًا ليس بالضرورة الأكثر دقة"]'::jsonb, '["المقياس 1: $\\frac{98.0 + 98.1 + 98.0}{3} = 98.03 \\approx 98.0$","المقياس 2: $\\frac{99.4 + 100.6 + 100.1}{3} = 100.03 \\approx 100.0$","المقياس 3: $\\frac{101.5 + 101.4 + 101.6}{3} = 101.5$","المقارنة بالقيمة المقبولة 100.0"]'::jsonb, '[{"element":"المتوسطات","marks":2},{"element":"الأكثر ضبطًا","marks":1},{"element":"المقارنة بالدقة","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة صحيحة"},{"level":"3–4 درجات","description":"خطأ في متوسط واحد أو تعليل ناقص في (ج)"},{"level":"1–2 درجة","description":"تحديد المقياس 2 دون حسابات أو مقارنة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ المقياس 1 الأكثر ضبطًا لأن قراءاته متقاربة","خطأ في حساب المتوسطات","الظن أن الأكثر ضبطًا هو الأكثر دقة دائمًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-18T12:34:59.086Z"}'::jsonb)
