('mcq', 5, 'كيف تتجنب خطأ اختلاف زاوية النظر عند قراءة ميزان نابضي؟', null, null, '["تنظر من أعلى الميزان لترى التدريج كاملًا","تقرأ بكلتا العينين من زاوية مائلة قليلًا","تنظر إلى المؤشر عموديًّا وبعين واحدة","تكرر القراءة من الزاوية المائلة نفسها"]'::jsonb, 'فهم', 'تفسير طريقة التجنب', 'سهل', 'الكتاب ص 20 — اختلاف زاوية النظر (الشكل 1-12)'),
('mcq', 6, 'ينظر طالب إلى مؤشر ميزان نابضي من موضع أعلى من مستوى المؤشر، وتزداد قيم التدريج إلى أسفل، والمؤشر يبعد قليلًا عن لوحة التدريج. كيف تكون قراءته؟', null, null, '["أصغر من القراءة الصحيحة","مساوية للقراءة الصحيحة لأن المؤشر لم يتحرك","مساوية للصحيحة ولكنها أقل دقة","أكبر من القراءة الصحيحة"]'::jsonb, 'تحليل', 'استنتاج اتجاه الخطأ', 'صعب', 'الكتاب ص 20 — اختلاف زاوية النظر (الشكل 1-12)'),
('mcq', 7, 'سجّل ثلاثة طلاب موضع المؤشر في الشكل الآتي من المواضع 1 و2 و3. أيّ مجموعات القراءات الآتية تطابق ما يراه الطلاب؟', null, '[{"src":"qimg/phys1/c1l2-plx-eyes3.svg","alt":"منظر جانبي: تدريج أفقي بالسنتيمتر مرقّم من 1 إلى 5 بتدريجات صغيرة كل 0.1 cm، ومؤشر رأسي مثبّت فوق التدريج بمسافة صغيرة وطرفه السفلي فوق العلامة 3 تمامًا. ثلاثة مواضع للعين: الموضع 1 أعلى يسار المؤشر، والموضع 2 فوق المؤشر مباشرة، والموضع 3 أعلى يمين المؤشر. من كل موضع خط نظر متقطع يمر بطرف المؤشر ويمتد حتى التدريج: خط الموضع 1 يصل إلى 3.4 cm، وخط الموضع 2 يصل إلى 3.0 cm، وخط الموضع 3 يصل إلى 2.6 cm."}]'::jsonb, '["الموضع 1: 3.4 cm، والموضع 2: 3.0 cm، والموضع 3: 2.6 cm","الموضع 1: 2.6 cm، والموضع 2: 3.0 cm، والموضع 3: 3.4 cm","الموضع 1: 3.0 cm، والموضع 2: 3.0 cm، والموضع 3: 3.0 cm","الموضع 1: 3.4 cm، والموضع 2: 3.0 cm، والموضع 3: 3.4 cm"]'::jsonb, 'تحليل', 'تحليل شكل', 'صعب', 'الكتاب ص 20 — اختلاف زاوية النظر (الشكل 1-12)'),
('essay', 1, 'فسّر المقصود باختلاف زاوية النظر، ثم وضّح كيف يمكن تجنبه عند قراءة تدريج أداة قياس.', null, null, null, 'فهم', 'تفسير مفهوم', 'سهل', 'الكتاب ص 20 — اختلاف زاوية النظر (الشكل 1-12)'),
('essay', 2, 'لماذا يؤثر اختلاف زاوية النظر في القياسات التي تجريها؟ وكيف تتجنب هذا الأثر عند قراءة التدريج؟', null, null, null, 'فهم', 'تفسير وتمييز', 'متوسط', 'الكتاب ص 20–21 — اختلاف زاوية النظر (سؤال المراجعة 16)'),
('essay', 3, 'يقرأ طالب موضع المؤشر من موضع العين المبين في الشكل الآتي. (أ) ما القراءة التي يسجلها؟ وما القراءة الصحيحة؟ (ب) احسب الفرق بينهما. (ج) فسّر سبب هذا الفرق وأثره في القياس، ثم بيّن كيف يصحح الطالب طريقته.', null, '[{"src":"qimg/phys1/c1l2-plx-right.svg","alt":"منظر جانبي: تدريج أفقي بالسنتيمتر مرقّم من 1 إلى 5 بتدريجات صغيرة كل 0.1 cm، ومؤشر رأسي مثبّت فوق التدريج بمسافة صغيرة وطرفه السفلي فوق العلامة 2.5 cm تمامًا. عين واحدة أعلى يمين المؤشر تنظر إليه بشكل مائل، وخط نظرها المتقطع يمر بطرف المؤشر ويمتد حتى يصل إلى التدريج عند العلامة 2.1 cm."}]'::jsonb, null, 'تطبيق', 'تحليل شكل وتفسير', 'صعب', 'الكتاب ص 20 — اختلاف زاوية النظر (الشكل 1-12)')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
