select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 1, 'اختلاف زاوية النظر هو التغير الظاهري في موقع الجسم عند النظر إليه من زوايا مختلفة.', '["هذا يتعلق بأصغر تدريج (الدقة)، لا بزاوية النظر.","","هذا مقدار بُعد النتيجة عن القيمة المقبولة، وقد ينتج عن أسباب متعددة.","الطول الحقيقي لا يتغير؛ الذي يتغير هو الموقع الظاهري عند النظر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-18T12:34:59.087Z"}'::jsonb),
('mcq', 2, 2, 'النظر العمودي فوق المؤشر مباشرة (الموضع 2) يعطي القراءة الصحيحة 3.0 cm؛ أما الموضعان المائلان فيعطيان قراءتين مختلفتين وغير مضبوطتين.', '["الموضع 1 مائل، فخط نظره يصل إلى 3.4 cm لا إلى موضع المؤشر الحقيقي.","الموضع 3 مائل، فخط نظره يصل إلى 2.6 cm.","","المؤشر ثابت فعلًا، لكن موقعه الظاهري على التدريج يتغير بتغير زاوية النظر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-18T12:34:59.087Z"}'::jsonb),
('mcq', 3, 0, 'خط النظر المائل يمر بطرف المؤشر ويصل إلى 3.4 cm، فيسجل الطالب قراءة غير مضبوطة، أما القراءة الصحيحة فهي موضع المؤشر 3.0 cm التي تُرى بالنظر العمودي.', '["","خط النظر من أعلى اليسار يمتد عبر المؤشر إلى اليمين (3.4 cm) لا إلى اليسار.","عكسٌ للقراءتين؛ فالصحيحة هي موضع المؤشر نفسه 3.0 cm.","القراءة من زاوية مائلة غير مضبوطة؛ والمؤشر يقع فوق 3.0 cm."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (48%)"}],"at":"2026-11-18T12:34:59.087Z"}'::jsonb),
('mcq', 4, 3, 'قراءة التدريج بشكل مائل تعطي قيمة مختلفة وغير مضبوطة؛ فاختلاف زاوية النظر خطأ شخصي يؤثر في الضبط.', '["زاوية النظر لا تغير تدريجات الأداة؛ فالدقة تعتمد على الأداة وتقارب القراءات.","القيمة المقبولة معتمدة ولا تتأثر بطريقة قراءة الطالب.","الوحدة لا تتغير بزاوية النظر.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-18T12:34:59.087Z"}'::jsonb),
('mcq', 5, 2, 'يُتجنب اختلاف زاوية النظر بقراءة التدريج بالنظر عموديًّا وبعين واحدة، أي بجعل العين في مستوى المؤشر.', '["النظر من أعلى يجعل خط النظر مائلًا فتختلف القراءة.","يجب النظر عموديًّا وبعين واحدة.","","التكرار من الزاوية نفسها يكرر الخطأ نفسه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-11-18T12:34:59.087Z"}'::jsonb),
('mcq', 6, 3, 'عند النظر من أعلى يمتد خط النظر عبر المؤشر إلى نقطة أسفل منه على لوحة التدريج، وبما أن القيم تزداد إلى أسفل فالقراءة أكبر من الصحيحة وغير مضبوطة.', '["خط النظر من أعلى يمر بالمؤشر ثم يتجه إلى أسفل، أي نحو القيم الأكبر.","المؤشر لم يتحرك، لكن موقعه الظاهري على التدريج تغيّر بسبب النظر المائل.","القراءة لا تكون مساوية للصحيحة، والأثر يقع على الضبط لا على الدقة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-18T12:34:59.087Z"}'::jsonb),
('mcq', 7, 0, 'كل خط نظر يمر بطرف المؤشر ويمتد إلى الجهة المقابلة للعين: الموضع 1 (يسار) → 3.4 cm، والموضع 2 (عمودي) → 3.0 cm، والموضع 3 (يمين) → 2.6 cm.', '["","عكسٌ لاتجاه امتداد خطي النظر المائلين؛ فخط الموضع 1 يمتد إلى اليمين.","الموقع الظاهري للمؤشر يتغير بتغير زاوية النظر، فلا تتساوى القراءات.","الموضعان 1 و3 على جانبين متقابلين، فينحرف خطا نظرهما في اتجاهين متعاكسين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-18T12:34:59.087Z"}'::jsonb),
('essay', 1, null::int, null, null, 'اختلاف زاوية النظر هو التغير الظاهري في موقع الجسم (أو المؤشر) عند النظر إليه من زوايا مختلفة؛ فإذا قُرئ التدريج بشكل مائل نحصل على قيمة مختلفة وغير مضبوطة. ولتجنبه تُقرأ التدريجات بالنظر عموديًّا عليها وبعين واحدة، بحيث تكون العين مقابلة للمؤشر مباشرة.', '["التعريف: تغير ظاهري في الموقع بتغير زاوية النظر","القراءة المائلة غير مضبوطة","التجنب: النظر العمودي","بعين واحدة"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف","marks":1},{"element":"الأثر","marks":1},{"element":"النظر العمودي","marks":1},{"element":"العين الواحدة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تفسير كامل مع طريقة التجنب"},{"level":"2–3 درجات","description":"نقص في الأثر أو في طريقة التجنب"},{"level":"1 درجة","description":"ذكر طريقة التجنب فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تعريفه بأنه تغير حقيقي في موقع الجسم","إغفال النظر بعين واحدة","اقتراح تكرار القياس لتجنبه"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-18T12:34:59.088Z"}'::jsonb),
('essay', 2, null::int, null, null, 'لأن قراءة التدريج بشكل مائل تُظهر المؤشر مقابلًا لتدريج غير التدريج الذي يقابله فعلًا، فنحصل على قيمة مختلفة عن القيمة الصحيحة وغير مضبوطة؛ وهو خطأ شخصي من القارئ لا من الأداة. ولتجنبه تُقرأ التدريجات بالنظر عموديًّا عليها وبعين واحدة، بحيث تكون العين مقابلة للمؤشر مباشرة، فتكون القراءة أضبط.', '["القراءة المائلة تعطي قيمة مختلفة عن الصحيحة (غير مضبوطة)","السبب: المؤشر يبدو مقابلًا لتدريج آخر عند النظر بزاوية","الخطأ شخصي من القارئ لا من الأداة","التجنب: النظر عموديًّا على التدريج وبعين واحدة"]'::jsonb, '[]'::jsonb, '[{"element":"بيان أن القراءة المائلة تعطي قيمة مختلفة عن الصحيحة","marks":1},{"element":"تفسير السبب (المؤشر يبدو مقابلًا لتدريج آخر)","marks":1},{"element":"أنه خطأ شخصي من القارئ","marks":1},{"element":"طريقة التجنب: النظر عموديًّا وبعين واحدة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"يبين أثر زاوية النظر في القراءة ويفسر سببه ويذكر أنه خطأ شخصي ويصف طريقة التجنب"},{"level":"2–3 درجات","description":"يبين الأثر ويذكر طريقة التجنب مع نقص في التفسير"},{"level":"1 درجة","description":"يذكر طريقة التجنب أو الأثر فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الظن أن زاوية النظر تغيّر قيمة أصغر تدريج في الأداة","الاكتفاء بقول «القراءة خاطئة» دون تفسير السبب أو طريقة التجنب","ملاحظة للمصحح: يُقبل وصف الأثر بلفظ «الدقة» كما ورد في سؤال الكتاب ص21، ما دام الطالب يبيّن أن القراءة المائلة تعطي قيمة مختلفة عن الصحيحة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-11-18T12:34:59.088Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) يسجل 2.1 cm، والقراءة الصحيحة 2.5 cm. (ب) الفرق $= 2.5 - 2.1 = 0.4\ \text{cm}$. (ج) السبب اختلاف زاوية النظر: خط النظر المائل من أعلى اليمين يمر بطرف المؤشر ثم يمتد إلى اليسار فيصل إلى قيمة أصغر من موضع المؤشر؛ فتكون القراءة غير مضبوطة. وللتصحيح يضع عينه فوق المؤشر مباشرة وينظر عموديًّا على التدريج وبعين واحدة.', '["القراءة المسجلة 2.1 cm","القراءة الصحيحة 2.5 cm","الفرق 0.4 cm","السبب: النظر المائل (اختلاف زاوية النظر)","الأثر في الضبط وطريقة التصحيح"]'::jsonb, '["الفرق $= 2.5 - 2.1 = 0.4\\ \\text{cm}$"]'::jsonb, '[{"element":"القراءتان","marks":2},{"element":"الفرق","marks":1},{"element":"السبب والأثر","marks":1},{"element":"التصحيح","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة صحيحة"},{"level":"3–4 درجات","description":"خطأ في إحدى القراءتين أو نقص في التفسير"},{"level":"1–2 درجة","description":"تحديد القراءة الصحيحة وطريقة التصحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["قراءة 2.9 cm بعكس اتجاه امتداد خط النظر","القول إن الخطأ يؤثر في الدقة","اقتراح تكرار القراءة من الموضع نفسه"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (48%)"}],"at":"2026-11-18T12:34:59.088Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
