insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'P1-C1-L2-O19'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'ما الفرق بين الدقة والضبط في القياس؟', null, null, '["الدقة اتفاق النتائج مع القيمة المقبولة، والضبط تقاربها بعضها من بعض","الدقة تقارب النتائج بعضها من بعض، والضبط اتفاقها مع القيمة المقبولة","الدقة تعتمد على القيمة المقبولة فقط، والضبط على الأداة فقط","لا فرق بينهما، فكلاهما يعبّر عن صحة نتيجة القياس"]'::jsonb, 'فهم', 'تمييز بين مفهومين', 'سهل', 'الكتاب ص 19–20، 25 — الدقة والضبط'),
('mcq', 2, 'إذا مثّل مركز كل هدف في الشكل الآتي القيمة المقبولة، فأيّ الأهداف يمثل قياسات دقيقة ولكنها غير مضبوطة؟', null, '[{"src":"qimg/phys1/c1l2-tgt-four.svg","alt":"أربعة أهداف رماية، مركز كل منها نقطة حمراء. الهدف 1: خمس إصابات متفرقة ومتباعدة تقع كلها في أعلى يمين الهدف بعيدًا عن المركز. الهدف 2: خمس إصابات متقاربة جدًّا بعضها من بعض متجمعة في أعلى يمين الهدف بعيدًا عن المركز. الهدف 3: خمس إصابات متفرقة موزعة حول المركز من جهاته المختلفة. الهدف 4: خمس إصابات متقاربة جدًّا ومتجمعة على المركز."}]'::jsonb, '["الهدف 4","الهدف 3","الهدف 1","الهدف 2"]'::jsonb, 'تحليل', 'تمييز من شكل', 'سهل', 'الكتاب ص 19–20 — الدقة والضبط'),
('mcq', 3, 'يبين الرسم الآتي نتائج ثلاثة طلاب في قياس زمن دورة بندول مع القيمة المقبولة. كيف توصف نتيجة الطالب A مقارنة بنتيجتي زميليه؟', null, '[{"src":"qimg/phys1/c1l2-eb-pend2.svg","alt":"رسم بياني بأعمدة خطأ: المحور الأفقي «الطالب» وعليه ثلاثة طلاب A وB وC، والمحور الرأسي «زمن الدورة (s)» من 1.80 إلى 2.20 بتدريج 0.05. خط أخضر أفقي متقطع عند 2.00 s مكتوب عليه «القيمة المقبولة». نتيجة A تساوي 2.10 s بعمود خطأ 0.01 s في كل اتجاه، ونتيجة B تساوي 1.99 s بعمود خطأ 0.08 s (يمتد من 1.91 إلى 2.07)، ونتيجة C تساوي 2.01 s بعمود خطأ 0.02 s."}]'::jsonb, '["الأكثر دقة والأقل ضبطًا","الأكثر دقة والأكثر ضبطًا","الأقل دقة والأقل ضبطًا","الأقل دقة والأكثر ضبطًا"]'::jsonb, 'تحليل', 'تمييز من رسم', 'صعب', 'الكتاب ص 19–20 — الدقة والضبط'),
('mcq', 4, 'لديك ميكرومتر منحنٍ بشكل سيئ (يقيس إلى أقرب 0.01 mm)، ومسطرة مترية ذات نوعية جيدة. كيف تقارن بينهما من حيث الدقة والضبط؟', null, null, '["المسطرة أكثر دقة، والميكرومتر أكثر ضبطًا","الميكرومتر أكثر دقة وضبطًا معًا","الميكرومتر أكثر دقة، والمسطرة أكثر ضبطًا","المسطرة أكثر دقة وضبطًا معًا"]'::jsonb, 'تحليل', 'مقارنة أداتين', 'متوسط', 'الكتاب ص 21 — سؤال المراجعة 15'),
('mcq', 5, 'استخدم العالمان A وB تقنية التأريخ بالكربون المشع لتحديد عمر رمحين، فوجد A أن عمر الرمح الأول $(2250 \pm 40)$ سنة، ووجد B أن عمر الرمح الثاني $(2215 \pm 50)$ سنة. أيّ العبارات الآتية صحيحة؟', null, null, '["قياس العالم A أكثر ضبطًا من قياس العالم B","قياس العالم A أكثر دقة من قياس العالم B","قياس العالم B أكثر ضبطًا من قياس العالم A","قياس العالم B أكثر دقة من قياس العالم A"]'::jsonb, 'تحليل', 'تمييز في موقف', 'متوسط', 'الكتاب ص 29 — السؤال 1'),
('mcq', 6, 'قاس طالب طول قضيب ثلاث مرات فحصل على 14.6 cm و14.6 cm و14.7 cm، علمًا بأن الطول المقبول للقضيب 15.4 cm. كيف توصف قياساته؟', null, null, '["مضبوطة لكنها غير دقيقة","دقيقة ومضبوطة","دقيقة لكنها غير مضبوطة","غير دقيقة وغير مضبوطة"]'::jsonb, 'فهم', 'تصنيف قياسات', 'سهل', 'الكتاب ص 19–20 — الدقة والضبط'),
('mcq', 7, 'أيّ العوامل الآتية يؤثر في ضبط القياس دون أن يغيّر دقة الأداة؟', null, null, '["تصغير قيمة أصغر تدريج في الأداة","استبدال مسطرة تدريجها 0.5 cm بأخرى تدريجها 0.1 cm","زيادة عدد التدريجات في كل سنتيمتر","خطأ في معايرة صفر الأداة"]'::jsonb, 'تحليل', 'تمييز عوامل', 'صعب', 'الكتاب ص 19–20 — الدقة والضبط ومعايرة النقطتين'),
('essay', 1, 'يمثل مركز كل هدف في الشكل الآتي القيمة المقبولة، وتمثل كل إصابة نتيجة قياس. صنّف نتائج كل هدف من حيث الدقة والضبط، مع التعليل.', null, '[{"src":"qimg/phys1/c1l2-tgt-four2.svg","alt":"أربعة أهداف رماية، مركز كل منها نقطة حمراء. الهدف 1: خمس إصابات متقاربة جدًّا ومتجمعة على المركز. الهدف 2: خمس إصابات متفرقة ومتباعدة تقع كلها في أعلى يمين الهدف بعيدًا عن المركز. الهدف 3: خمس إصابات متقاربة جدًّا بعضها من بعض متجمعة في أعلى يمين الهدف بعيدًا عن المركز. الهدف 4: خمس إصابات متفرقة موزعة حول المركز من جهاته المختلفة."}]'::jsonb, null, 'تحليل', 'تصنيف من شكل', 'متوسط', 'الكتاب ص 19–20 — الدقة والضبط'),
('essay', 2, 'يبين الرسم الآتي نتائج ثلاثة طلاب في قياس زمن دورة بندول مع القيمة المقبولة. (أ) أيّ النتائج أكثر دقة؟ وأيّها أقل دقة؟ (ب) قارن بين النتائج من حيث الضبط. (ج) أيّ النتائج تثق بها أكثر؟ علّل.', null, '[{"src":"qimg/phys1/c1l2-eb-pend3.svg","alt":"رسم بياني بأعمدة خطأ: المحور الأفقي «الطالب» وعليه ثلاثة طلاب A وB وC، والمحور الرأسي «زمن الدورة (s)» من 1.80 إلى 2.20 بتدريج 0.05. خط أخضر أفقي متقطع عند 2.00 s مكتوب عليه «القيمة المقبولة». نتيجة A تساوي 2.10 s بعمود خطأ 0.01 s في كل اتجاه، ونتيجة B تساوي 1.99 s بعمود خطأ 0.08 s (يمتد من 1.91 إلى 2.07)، ونتيجة C تساوي 2.01 s بعمود خطأ 0.02 s."}]'::jsonb, null, 'تحليل', 'مقارنة من رسم', 'متوسط', 'الكتاب ص 19–20 — الدقة والضبط'),
('essay', 3, 'قوّم العبارة الآتية: «القياس الدقيق يكون دائمًا مضبوطًا». أيّد رأيك بمثال عددي.', null, null, null, 'تقويم', 'تقويم عبارة', 'صعب', 'الكتاب ص 19–20 — الدقة والضبط')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'P1-C1-L2-O19') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 1, 'دقة القياس تعبر عن مدى تقارب نتائج القياس بغض النظر عن صحتها، والضبط يصف اتفاق النتائج مع القيمة المقبولة.', '["تبديل بين المفهومين.","","الدقة تعتمد على الأداة والطريقة، والضبط يُحكم عليه بالمقارنة بالقيمة المقبولة.","الدقة تعبر عن تقارب النتائج بغض النظر عن صحتها، والضبط يعبر عن صحتها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-18T12:34:59.088Z"}'::jsonb),
('mcq', 2, 3, 'الدقة تقارب الإصابات بعضها من بعض، والضبط قربها من المركز. إصابات الهدف 2 متقاربة جدًّا لكنها بعيدة عن المركز.', '["إصابات الهدف 4 متقاربة وعلى المركز؛ فهي دقيقة ومضبوطة.","إصابات الهدف 3 متفرقة حول المركز؛ فهي غير دقيقة.","إصابات الهدف 1 متفرقة وبعيدة عن المركز؛ فهي غير دقيقة وغير مضبوطة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-11-18T12:34:59.089Z"}'::jsonb),
('mcq', 3, 0, 'هامش خطأ A (0.01 s) أصغر من هامشي B (0.08 s) وC (0.02 s) فهي الأكثر دقة، لكنها تبعد 0.10 s عن 2.00 s مقابل 0.01 s لكل من B وC فهي الأقل ضبطًا.', '["","نتيجة A هي الأبعد عن القيمة المقبولة (0.10 s)، فهي الأقل ضبطًا.","هامش خطأ A هو الأصغر (0.01 s)، فهي الأكثر دقة.","عكسٌ للوصفين معًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (41%)"}],"at":"2026-11-18T12:34:59.089Z"}'::jsonb),
('mcq', 4, 2, 'الدقة تعتمد على أصغر تدريج: الميكرومتر أدق. أما الضبط فاتفاق القراءات مع القيم الصحيحة، والانحناء يُفسد ضبط الميكرومتر، فالمسطرة الجيدة أكثر ضبطًا.', '["تبديل؛ فأصغر تدريج في الميكرومتر أصغر بكثير، لكن انحناءه يُبعد قراءاته عن الصحيحة.","صغر التدريج يجعله أدق، لكن انحناءه يجعل قراءاته غير مضبوطة.","","أصغر تدريج في المسطرة (1 mm) أكبر من 0.01 mm، فهي أقل دقة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-18T12:34:59.089Z"}'::jsonb),
('mcq', 5, 1, 'الدقة تُعرف من هامش الخطأ: هامش A (40 سنة) أصغر من هامش B (50 سنة)، فقياس A أكثر دقة. أما الضبط فيحتاج إلى قيمة مقبولة غير معطاة هنا.', '["لا يمكن الحكم على الضبط دون قيمة مقبولة لعمر كل رمح.","","الحكم على الضبط يحتاج إلى قيمة مقبولة، وهي غير معطاة.","هامش خطأ B (50 سنة) أكبر من هامش A (40 سنة)، فـ B أقل دقة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (3%)"}],"at":"2026-11-18T12:34:59.089Z"}'::jsonb),
('mcq', 6, 2, 'القراءات متقاربة (فرقها 0.1 cm) فهي دقيقة، لكنها تبعد نحو 0.8 cm عن القيمة المقبولة 15.4 cm فهي غير مضبوطة.', '["القراءات متقاربة جدًّا فهي دقيقة، وبعيدة عن 15.4 cm فهي غير مضبوطة.","القراءات تبعد نحو 0.8 cm عن القيمة المقبولة، فهي غير مضبوطة.","","القراءات تختلف 0.1 cm فقط بعضها عن بعض، فهي دقيقة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-11-18T12:34:59.089Z"}'::jsonb),
('mcq', 7, 3, 'خطأ معايرة الصفر يُبعد جميع القراءات عن القيمة المقبولة فيؤثر في الضبط، ولا يغيّر أصغر تدريج في الأداة فلا تتغير دقتها.', '["تصغير أصغر تدريج يزيد دقة الأداة.","هذا الاستبدال يغيّر الدقة من 0.25 cm إلى 0.05 cm.","زيادة التدريجات تعني تدريجًا أصغر، أي دقة أكبر.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-18T12:34:59.089Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الهدف 1: دقيقة ومضبوطة (الإصابات متقاربة وعلى المركز). الهدف 2: غير دقيقة وغير مضبوطة (متفرقة وبعيدة عن المركز). الهدف 3: دقيقة وغير مضبوطة (متقاربة لكنها بعيدة عن المركز). الهدف 4: غير دقيقة (متفرقة)، ونتائجها موزعة حول المركز فمتوسطها قريب من القيمة المقبولة، لكن كل نتيجة منفردة بعيدة عنها فضبطها أقل من الهدف 1.', '["الهدف 1: دقيقة ومضبوطة","الهدف 2: غير دقيقة وغير مضبوطة","الهدف 3: دقيقة وغير مضبوطة","الهدف 4: غير دقيقة وموزعة حول القيمة المقبولة","التعليل: الدقة = التقارب، والضبط = القرب من المركز"]'::jsonb, '[]'::jsonb, '[{"element":"الهدف 1","marks":1},{"element":"الهدف 2","marks":1},{"element":"الهدف 3","marks":1},{"element":"الهدف 4","marks":1},{"element":"التعليل","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"تصنيف صحيح للأهداف الأربعة مع التعليل"},{"level":"3–4 درجات","description":"خطأ في تصنيف هدف واحد أو تعليل ناقص"},{"level":"1–2 درجة","description":"تصنيف صحيح لهدف أو هدفين"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ الهدف 3 مضبوطًا لتقارب إصاباته","الخلط بين الدقة والضبط","إغفال التعليل"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-11-18T12:34:59.090Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) الأكثر دقة نتيجة A (هامش $\pm 0.01\ \text{s}$)، والأقل دقة نتيجة B (هامش $\pm 0.08\ \text{s}$). (ب) A تبعد 0.10 s عن 2.00 s فهي الأقل ضبطًا، وB وC تبعد كل منهما 0.01 s فهما متساويتان تقريبًا في الضبط وأكثر ضبطًا من A. (ج) نتيجة C؛ لأنها تجمع بين الدقة العالية (هامش 0.02 s) والضبط (تبعد 0.01 s فقط).', '["A الأكثر دقة","B الأقل دقة","A الأقل ضبطًا، وB وC أكثر ضبطًا","C الأجدر بالثقة لجمعها الدقة والضبط"]'::jsonb, '["A: الفرق = $2.10 - 2.00 = 0.10\\ \\text{s}$","B: الفرق $= 2.00 - 1.99 = 0.01\\ \\text{s}$","C: الفرق $= 2.01 - 2.00 = 0.01\\ \\text{s}$"]'::jsonb, '[{"element":"الدقة","marks":1},{"element":"الضبط","marks":2},{"element":"الاختيار والتعليل","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة"},{"level":"2–3 درجات","description":"خطأ في جزء واحد"},{"level":"1 درجة","description":"تحديد الأكثر دقة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["اختيار A لأن هامش خطئها أصغر","عدّ B الأقل ضبطًا لأن هامشها كبير","الخلط بين الدقة والضبط"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (41%)"}],"at":"2026-11-18T12:34:59.090Z"}'::jsonb),
('essay', 3, null::int, null, null, 'العبارة غير صحيحة؛ فالدقة تعبر عن تقارب نتائج القياس بغض النظر عن صحتها، والضبط يصف اتفاقها مع القيمة المقبولة. قد تكون القياسات متقاربة جدًّا ومع ذلك بعيدة عن القيمة المقبولة. مثال: قاس طالب طول قضيب طوله المقبول 15.4 cm بمسطرة لا يبدأ صفرها عند حافتها، فحصل على 14.6 و14.6 و14.7 cm؛ القراءات دقيقة (متقاربة) لكنها غير مضبوطة (تبعد نحو 0.8 cm).', '["العبارة غير صحيحة","تعريف الدقة","تعريف الضبط","مثال عددي صحيح لقياس دقيق غير مضبوط"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم","marks":1},{"element":"التمييز بين المفهومين","marks":1},{"element":"المثال العددي","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"حكم صحيح مع تمييز ومثال عددي مناسب"},{"level":"2–3 درجات","description":"حكم صحيح مع مثال غير عددي أو تمييز ناقص"},{"level":"1 درجة","description":"حكم صحيح دون تعليل"},{"level":"صفر","description":"الموافقة على العبارة أو لا إجابة"}]'::jsonb, '["الموافقة على العبارة","إعطاء مثال لقياس مضبوط غير دقيق بدل المطلوب","الخلط بين الدقة والضبط"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-18T12:34:59.090Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'P1-C1-L2-O19') and x.type = v.type and x.number = v.number
