('mcq', 3, 'اكتب قراءة الأميتر المبين في الشكل الآتي متضمنة خطأ القياس.', null, '[{"src":"qimg/phys1/c1l2-dial-amm.svg","alt":"عداد بمؤشر (أميتر) مكتوب عليه الحرف A، تدريجه على قوس مرقّم 0 و1 و2 و3 و4 و5، وبين كل رقمين أربعة تدريجات صغيرة تقسم المسافة خمسة أقسام متساوية (أصغر تدريج 0.2 A). المؤشر الأحمر يقف عند التدريج الصغير الثالث بعد الرقم 3 تمامًا."}]'::jsonb, '["$(3.6 \\pm 0.2)\\ \\text{A}$","$(3.3 \\pm 0.05)\\ \\text{A}$","$(3.6 \\pm 0.5)\\ \\text{A}$","$(3.6 \\pm 0.1)\\ \\text{A}$"]'::jsonb, 'تطبيق', 'قراءة عداد مع خطأ القياس', 'متوسط', 'الكتاب ص 19، 27 — خطأ القياس (السؤال 37)'),
('mcq', 4, 'اكتب قراءة الميزان النابضي المبين في الشكل الآتي متضمنة خطأ القياس.', null, '[{"src":"qimg/phys1/c1l2-spring-n.svg","alt":"ميزان نابضي رأسي مكتوب عليه N، تدريجه يزداد من أعلى إلى أسفل ومرقّم 0 و1 و2 و3 و4 و5، وبين كل رقمين تدريج قصير عند المنتصف (أصغر تدريج 0.5 N). المؤشر الأحمر يقف عند تدريج المنتصف بين 3 و4 تمامًا."}]'::jsonb, '["$(3.5 \\pm 0.5)\\ \\text{N}$","$(3.5 \\pm 0.25)\\ \\text{N}$","$(1.5 \\pm 0.25)\\ \\text{N}$","$(3.5 \\pm 1)\\ \\text{N}$"]'::jsonb, 'تطبيق', 'قراءة أداة مع خطأ القياس', 'متوسط', 'الكتاب ص 19 — دقة القياس وخطأ القياس (الشكل 1-10)'),
('mcq', 5, 'سجّل طالب طول نابض بالصورة $(14.6 \pm 0.2)\ \text{cm}$. ماذا تعني هذه النتيجة؟', null, null, '["أن الطول يساوي 14.8 cm تمامًا","أن الطول يقع بين 14.6 cm و14.8 cm فقط","أن الطول يقع على الأرجح بين 14.2 cm و15.0 cm","أن الطول يقع على الأرجح بين 14.4 cm و14.8 cm"]'::jsonb, 'فهم', 'تفسير صيغة خطأ القياس', 'سهل', 'الكتاب ص 19 — قياسات الطلاب'),
('mcq', 6, 'قاس طالب زمن سقوط كرة عدة مرات فتراوحت قراءاته بين 2.31 s و2.45 s، وكان متوسطها 2.38 s. كيف يعبّر عن نتيجته متضمنة خطأ القياس؟', null, null, '["$(2.38 \\pm 0.14)\\ \\text{s}$","$(2.31 \\pm 0.07)\\ \\text{s}$","$(2.38 \\pm 0.07)\\ \\text{s}$","$(2.45 \\pm 0.07)\\ \\text{s}$"]'::jsonb, 'تطبيق', 'التعبير عن نتيجة مع الخطأ', 'صعب', 'الكتاب ص 19 — قياسات الطالب الأول'),
('mcq', 7, 'قاس طالب طول القلم المبين في الشكل الآتي فكتب النتيجة $(4.25 \pm 0.05)\ \text{cm}$. بين أيّ قيمتين يقع طول القلم على الأرجح؟', null, '[{"src":"qimg/phys1/c1l2-rul-mm2.svg","alt":"مسطرة تدريجها بالسنتيمتر مرقّم من 0 إلى 5، وبين كل رقمين عشرة تدريجات صغيرة (أصغر تدريج 0.1 cm). فوق المسطرة قلم طرفه الأيسر عند علامة الصفر تمامًا، ورأسه المدبب يقع في منتصف المسافة بين العلامتين 4.2 cm و4.3 cm."}]'::jsonb, '["بين 4.15 cm و4.35 cm","بين 4.20 cm و4.30 cm","بين 4.25 cm و4.30 cm","بين 3.75 cm و4.75 cm"]'::jsonb, 'تطبيق', 'تفسير نتيجة مع الخطأ', 'صعب', 'الكتاب ص 19 — دقة القياس وخطأ القياس (الشكل 1-10)'),
('essay', 1, 'استخدم المسطرة المبينة في الشكل الآتي للإجابة عما يأتي: (أ) ما قيمة أصغر تدريج فيها؟ وما خطأ القياس بها؟ (ب) اكتب طول القلم متضمنًا خطأ القياس. (ج) بين أيّ قيمتين يقع طول القلم على الأرجح؟', null, '[{"src":"qimg/phys1/c1l2-rul-o20e.svg","alt":"مسطرة تدريجها بالسنتيمتر مرقّم من 0 إلى 8، وبين كل رقمين عشرة تدريجات صغيرة (أصغر تدريج 0.1 cm). فوق المسطرة قلم طرفه الأيسر عند علامة الصفر تمامًا، ورأسه المدبب يقع في منتصف المسافة بين العلامتين 6.4 cm و6.5 cm."}]'::jsonb, null, 'تطبيق', 'قراءة أداة مع خطأ القياس', 'سهل', 'الكتاب ص 19، 26 — خطأ القياس (السؤال 31)'),
('essay', 2, 'أجرى طالب تجربة قياس طول نابض ثلاث مرات فحصل على 25.3 cm و25.7 cm و25.5 cm. (أ) احسب متوسط قياساته. (ب) عبّر عن نتيجته متضمنة خطأ القياس (استخدم نصف مدى القراءات). (ج) ماذا يعني هامش الخطأ في نتيجتك؟', null, null, null, 'تطبيق', 'حساب وتعبير عن نتيجة', 'متوسط', 'الكتاب ص 19 — قياسات الطلاب'),
('essay', 3, 'يبين الشكل الآتي فولتميترًا بمؤشر. (أ) حدّد أصغر تدريج فيه وخطأ القياس به. (ب) اكتب القراءة متضمنة خطأ القياس. (ج) إذا استُبدل به فولتميتر أصغر تدريج فيه 0.1 V وأعطى القراءة نفسها، فاكتب القراءة الجديدة متضمنة خطأ القياس، وبيّن أيّ الجهازين أكثر دقة.', null, '[{"src":"qimg/phys1/c1l2-dial-volt.svg","alt":"عداد بمؤشر (فولتميتر) مكتوب عليه الحرف V، تدريجه على قوس مرقّم من 0 إلى 10، وبين كل رقمين تدريج صغير واحد عند المنتصف (أصغر تدريج 0.5 V). المؤشر الأحمر يقف عند تدريج المنتصف بين 7 و8 تمامًا."}]'::jsonb, null, 'تطبيق', 'قراءة عداد مع خطأ القياس', 'صعب', 'الكتاب ص 19، 27 — دقة القياس وخطأ القياس (السؤال 37)')
