from (values
('mcq', 1, 2, 'أصغر تدريج 0.1 cm، فخطأ القياس نصفه 0.05 cm. رأس القلم في منتصف المسافة بين 3.6 و3.7، فالطول $(3.65 \pm 0.05)\ \text{cm}$.', '["استُخدم أصغر تدريج كاملًا (0.1 cm) خطأً للقياس؛ والخطأ يساوي نصف أصغر تدريج.","أُهمل الجزء الواقع بعد العلامة 3.6؛ فرأس القلم في منتصف المسافة بين 3.6 و3.7.","","خلط بين المليمتر والسنتيمتر؛ فنصف أصغر تدريج 0.05 cm لا 0.5 cm."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (50%)"}],"at":"2026-11-18T12:34:59.091Z"}'::jsonb),
('mcq', 2, 0, 'أصغر تدريج في المسطرة 0.5 cm، فالخطأ $0.5 \div 2 = 0.25\ \text{cm}$، ورأس القلم عند تدريج المنتصف بين 3 و4، فالطول $(3.5 \pm 0.25)\ \text{cm}$.', '["","استُخدم أصغر تدريج كاملًا (0.5 cm)؛ والخطأ نصفه 0.25 cm.","افتُرض أن أصغر تدريج 0.1 cm، مع أن أصغر تدريج في هذه المسطرة 0.5 cm.","قُرئ آخر رقم مكتوب قبل رأس القلم وأُهمل تدريج المنتصف."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-18T12:34:59.091Z"}'::jsonb),
('mcq', 3, 3, 'بين كل رقمين خمسة أقسام، فأصغر تدريج $1 \div 5 = 0.2\ \text{A}$، والخطأ نصفه 0.1 A. المؤشر عند التدريج الثالث بعد 3، أي $3 + 3 \times 0.2 = 3.6\ \text{A}$؛ فالقراءة $(3.6 \pm 0.1)\ \text{A}$.', '["استُخدم أصغر تدريج كاملًا (0.2 A) خطأً للقياس؛ والخطأ نصفه.","عُدّ كل تدريج صغير 0.1 A، مع أن المسافة بين رقمين مقسومة خمسة أقسام (0.2 A لكل قسم).","الخطأ 0.5 A لا علاقة له بتدريجات هذا العداد؛ فأصغر تدريج 0.2 A.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (73%)"}],"at":"2026-11-18T12:34:59.091Z"}'::jsonb),
('mcq', 4, 1, 'أصغر تدريج 0.5 N، فالخطأ 0.25 N، والمؤشر عند منتصف المسافة بين 3 و4؛ فالقراءة $(3.5 \pm 0.25)\ \text{N}$.', '["استُخدم أصغر تدريج كاملًا (0.5 N)؛ والخطأ نصفه 0.25 N.","","قُرئ التدريج من الأسفل إلى الأعلى، مع أن القيم تزداد إلى أسفل وتبدأ من الصفر في الأعلى.","استُخدمت المسافة بين رقمين (1 N) خطأً، مع وجود تدريج عند المنتصف."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (73%)"}],"at":"2026-11-18T12:34:59.091Z"}'::jsonb),
('mcq', 5, 3, 'الصيغة $(14.6 \pm 0.2)\ \text{cm}$ تعني أن القيمة 14.6 cm وأن خطأ القياس 0.2 cm في الاتجاهين، أي بين 14.4 cm و14.8 cm.', '["العدد 0.2 هامش خطأ يُضاف ويُطرح، ولا يُجمع مع القيمة لتصبح قيمة واحدة.","الهامش يكون في الاتجاهين، فيشمل القيم الأقل من 14.6 cm أيضًا.","ضوعف الهامش؛ فالمدى من $14.6 - 0.2$ إلى $14.6 + 0.2$ فقط.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-18T12:34:59.091Z"}'::jsonb),
('mcq', 6, 2, 'القيمة هي المتوسط 2.38 s، والهامش نصف المدى $\frac{2.45 - 2.31}{2} = 0.07\ \text{s}$، فالنتيجة $(2.38 \pm 0.07)\ \text{s}$ وتغطي القراءات من 2.31 s إلى 2.45 s.', '["استُخدم المدى كاملًا (0.14 s) هامشًا للخطأ؛ والهامش نصف المدى لأنه يُضاف ويُطرح.","كُتبت أصغر قراءة قيمةً للنتيجة بدل المتوسط.","","كُتبت أكبر قراءة قيمةً للنتيجة بدل المتوسط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-18T12:34:59.091Z"}'::jsonb),
('mcq', 7, 1, 'الحد الأدنى $4.25 - 0.05 = 4.20\ \text{cm}$، والحد الأعلى $4.25 + 0.05 = 4.30\ \text{cm}$، ويتفق ذلك مع وقوع رأس القلم بين العلامتين 4.2 و4.3.', '["ضوعف هامش الخطأ؛ فالمدى 0.05 cm فقط على كل جانب.","","أُخذ الهامش في اتجاه واحد فقط؛ والهامش يُطرح أيضًا.","استُخدم 0.5 cm بدل 0.05 cm."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-18T12:34:59.091Z"}'::jsonb),
('essay', 1, null::int, null, null, '(أ) أصغر تدريج 0.1 cm، وخطأ القياس نصفه 0.05 cm. (ب) رأس القلم في منتصف المسافة بين 6.4 و6.5، فالطول $(6.45 \pm 0.05)\ \text{cm}$. (ج) بين 6.40 cm و6.50 cm.', '["أصغر تدريج 0.1 cm","خطأ القياس 0.05 cm","الطول $(6.45 \\pm 0.05)\\ \\text{cm}$","المدى من 6.40 cm إلى 6.50 cm"]'::jsonb, '["خطأ القياس $= 0.1 \\div 2 = 0.05\\ \\text{cm}$","القراءة: 6.45 cm","المدى: $6.45 - 0.05 = 6.40$ و$6.45 + 0.05 = 6.50$"]'::jsonb, '[{"element":"أصغر تدريج والخطأ","marks":1},{"element":"القراءة مع الخطأ","marks":2},{"element":"المدى","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة"},{"level":"2–3 درجات","description":"خطأ في المدى أو في رقم القراءة الأخير"},{"level":"1 درجة","description":"تحديد أصغر تدريج فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة الخطأ 0.1 cm بدل 0.05 cm","إهمال الجزء بعد 6.4","كتابة الهامش في اتجاه واحد"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-11-18T12:34:59.092Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) المتوسط $= \frac{25.3 + 25.7 + 25.5}{3} = 25.5\ \text{cm}$. (ب) نصف المدى $= \frac{25.7 - 25.3}{2} = 0.2\ \text{cm}$، فالنتيجة $(25.5 \pm 0.2)\ \text{cm}$. (ج) يعني أن طول النابض يقع على الأرجح بين 25.3 cm و25.7 cm، وكلما صغر الهامش كانت القياسات أكثر دقة.', '["المتوسط 25.5 cm","الهامش 0.2 cm","النتيجة $(25.5 \\pm 0.2)\\ \\text{cm}$","تفسير الهامش"]'::jsonb, '["المتوسط $= \\frac{25.3 + 25.7 + 25.5}{3} = 25.5\\ \\text{cm}$","المدى $= 25.7 - 25.3 = 0.4\\ \\text{cm}$","الهامش $= 0.4 \\div 2 = 0.2\\ \\text{cm}$","النتيجة $(25.5 \\pm 0.2)\\ \\text{cm}$"]'::jsonb, '[{"element":"المتوسط","marks":1},{"element":"الهامش","marks":1},{"element":"كتابة النتيجة","marks":1},{"element":"التفسير","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة"},{"level":"2–3 درجات","description":"خطأ في الهامش أو التفسير"},{"level":"1 درجة","description":"حساب المتوسط فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["استخدام المدى كاملًا (0.4 cm) هامشًا","كتابة النتيجة دون وحدة","تفسير الهامش بأنه الخطأ عن القيمة المقبولة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-18T12:34:59.092Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) بين كل رقمين قسمان، فأصغر تدريج 0.5 V، وخطأ القياس نصفه 0.25 V. (ب) المؤشر عند منتصف المسافة بين 7 و8، فالقراءة $(7.5 \pm 0.25)\ \text{V}$. (ج) الخطأ الجديد $0.1 \div 2 = 0.05\ \text{V}$، فالقراءة $(7.50 \pm 0.05)\ \text{V}$، والجهاز الثاني أكثر دقة لأن تدريجه أصغر.', '["أصغر تدريج 0.5 V","الخطأ 0.25 V","القراءة $(7.5 \\pm 0.25)\\ \\text{V}$","القراءة الجديدة $(7.50 \\pm 0.05)\\ \\text{V}$","الجهاز الثاني أكثر دقة"]'::jsonb, '["أصغر تدريج $= 1 \\div 2 = 0.5\\ \\text{V}$","الخطأ $= 0.5 \\div 2 = 0.25\\ \\text{V}$","الخطأ الجديد $= 0.1 \\div 2 = 0.05\\ \\text{V}$"]'::jsonb, '[{"element":"أصغر تدريج والخطأ","marks":1},{"element":"القراءة الأولى","marks":1},{"element":"القراءة الثانية","marks":2},{"element":"المقارنة","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة صحيحة"},{"level":"3–4 درجات","description":"خطأ في إحدى القراءتين أو المقارنة"},{"level":"1–2 درجة","description":"تحديد أصغر تدريج والخطأ فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة الخطأ مساويًا لأصغر تدريج","قراءة 7 V أو 8 V وإهمال المنتصف","الحكم بأن الجهاز الأول أكثر دقة لأن هامشه أكبر"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-18T12:34:59.092Z"}'::jsonb)
