('mcq', 1, 'حسب طالب سرعة سيارة بعدة خطوات. أيّ وحدات الإجابة النهائية تدل على أن حله سليم من حيث الوحدات؟', null, null, '["$\\text{s/m}$","$\\text{m/s}$","$\\text{m/s}^2$","$\\text{m}\\cdot\\text{s}$"]'::jsonb, 'تطبيق', 'التحقق بالوحدات', 'سهل', 'الكتاب ص 18 — تحليل الوحدات'),
('mcq', 2, 'يقاس الضغط بوحدة الباسكال، حيث $1\ \text{Pa} = 1\ \text{kg/(m}\cdot\text{s}^2)$. هل يمثل التعبير $\frac{(0.55\ \text{kg})(2.1\ \text{m/s})}{9.80\ \text{m/s}^2}$ قياسًا للضغط بوحدات صحيحة؟', null, null, '["لا؛ لأن وحدته $\\text{kg}\\cdot\\text{s}$","نعم؛ لأن وحدته $\\text{kg/(m}\\cdot\\text{s}^2)$","لا؛ لأن وحدته $\\text{kg}\\cdot\\text{m}^2/\\text{s}^3$","نعم؛ لأن جميع كمياته بوحدات النظام الدولي"]'::jsonb, 'تطبيق', 'التحقق بالوحدات', 'متوسط', 'الكتاب ص 27 — السؤال 33'),
('mcq', 3, 'إذا كانت $d$ مسافة بوحدة m، و$v$ سرعة بوحدة m/s، و$t$ زمنًا بوحدة s، فأيّ المعادلات الآتية صحيحة من حيث الوحدات؟', null, null, '["$d = \\frac{v}{t}$","$d = \\frac{t}{v}$","$d = vt^2$","$d = vt$"]'::jsonb, 'تطبيق', 'التحقق من معادلة', 'سهل', 'الكتاب ص 18 — تحليل الوحدات'),
('mcq', 4, 'تُحسب القوة المغناطيسية المؤثرة في شحنة متحركة من العلاقة $\boldsymbol{F} = Bqv$، حيث $F$ بوحدة $\text{N} = \text{kg}\cdot\text{m/s}^2$، و$q$ بوحدة $\text{A}\cdot\text{s}$، و$v$ بوحدة m/s. ما وحدة $B$ التي تجعل المعادلة صحيحة من حيث الوحدات؟', null, null, '["$\\text{kg}\\cdot\\text{m/(A}\\cdot\\text{s}^3)$","$\\text{kg/(A}\\cdot\\text{s)}$","$\\text{kg/(A}\\cdot\\text{s}^2)$","$\\text{kg}\\cdot\\text{m}^2/(\\text{A}\\cdot\\text{s}^4)$"]'::jsonb, 'تطبيق', 'استنتاج وحدة', 'صعب', 'الكتاب ص 21 — سؤال المراجعة 13a'),
('mcq', 5, 'حسب طالب تسارع جسم فحصل على إجابة بوحدة m/s. ماذا تستنتج؟', null, null, '["الإجابة صحيحة؛ لأن وحدة التسارع m/s","في الحل خطأ؛ لأن وحدة التسارع $\\text{m/s}^2$","الإجابة صحيحة إذا كانت قيمتها العددية موجبة","يجب ضرب الإجابة في 1000 لتصبح صحيحة"]'::jsonb, 'تطبيق', 'تقويم إجابة بالوحدات', 'متوسط', 'الكتاب ص 18 — تحليل الوحدات'),
('mcq', 6, 'إذا أُعطيت المسافة بوحدة km، والسرعة بوحدة m/s، فأيّ العمليات الآتية تعطي الزمن بوحدة الثانية (s)؟', null, null, '["قسمة المسافة على السرعة، ثم ضرب الناتج في 1000","ضرب المسافة في السرعة، ثم ضرب الناتج في 1000","قسمة المسافة على السرعة، ثم قسمة الناتج على 1000","ضرب المسافة في السرعة، ثم قسمة الناتج على 1000"]'::jsonb, 'تطبيق', 'اختيار عملية بالوحدات', 'متوسط', 'الكتاب ص 29 — السؤال 3'),
('mcq', 7, 'أثرت قوة مقدارها 2.7 N في جسم كتلته 350 g. أيّ التعويضات الآتية يعطي التسارع بوحدة $\text{m/s}^2$ (علمًا بأن $1\ \text{N} = 1\ \text{kg}\cdot\text{m/s}^2$)؟', null, null, '["$a = \\frac{2.7\\ \\text{N}}{350\\ \\text{g}} \\times \\frac{1\\ \\text{kg}}{1000\\ \\text{g}}$","$a = \\frac{2.7\\ \\text{N}}{350\\ \\text{g}}$","$a = (2.7\\ \\text{N})(350\\ \\text{g})$","$a = \\frac{2.7\\ \\text{N}}{350\\ \\text{g}} \\times \\frac{1000\\ \\text{g}}{1\\ \\text{kg}}$"]'::jsonb, 'تطبيق', 'التحقق من تعويض بالوحدات', 'صعب', 'الكتاب ص 29 — السؤال 6'),
('essay', 1, 'استخدم تحليل الوحدات لتتحقق من أن العلاقة $d = \frac{1}{2}at^2$ تعطي المسافة $d$ بوحدة صحيحة، علمًا بأن $a$ تسارع بوحدة $\text{m/s}^2$، و$t$ زمن بوحدة s.', null, null, null, 'تطبيق', 'التحقق من معادلة', 'سهل', 'الكتاب ص 18 — تحليل الوحدات'),
('essay', 2, 'بروتون شحنته $1.6 \times 10^{-19}\ \text{A}\cdot\text{s}$ يتحرك بسرعة $2.4 \times 10^5\ \text{m/s}$ عموديًّا على مجال مغناطيسي شدته 4.5 T، حيث $1\ \text{T} = 1\ \text{kg/(A}\cdot\text{s}^2)$. (أ) عوّض بالقيم في المعادلة $\boldsymbol{F} = Bqv$، وتحقق من صحة المعادلة بتعويض الوحدات في طرفيها. (ب) احسب مقدار القوة المغناطيسية المؤثرة في البروتون.', null, null, null, 'تطبيق', 'تحقق بالوحدات وحساب', 'متوسط', 'الكتاب ص 21 — سؤال المراجعة 13'),
('essay', 3, 'كتب طالب لحساب الزمن اللازم لقطع مسافة $d$ بسرعة ثابتة $v$ العلاقة $t = \frac{v}{d}$، ثم عوّض فيها $d = 150\ \text{m}$ و$v = 30\ \text{m/s}$. (أ) استخدم تحليل الوحدات لتقويم علاقته. (ب) اكتب العلاقة الصحيحة واحسب الزمن، متحققًا من وحدة الناتج.', null, null, null, 'تقويم', 'تقويم علاقة بالوحدات', 'صعب', 'الكتاب ص 18 — تحليل الوحدات')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
