('mcq', 1, 1, 'وحدة السرعة m/s؛ فإذا ظهرت الإجابة بوحدة s/m أو m/s² فهناك خطأ في حل المسألة.', '["هذه مقلوب وحدة السرعة؛ فظهورها يدل على خطأ في الحل.","","هذه وحدة التسارع لا السرعة.","حاصل ضرب المسافة في الزمن لا يعطي سرعة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-18T12:34:59.093Z"}'::jsonb),
('mcq', 2, 0, '$\frac{\text{kg}\cdot\text{m/s}}{\text{m/s}^2} = \text{kg}\cdot\frac{\text{m}}{\text{s}}\cdot\frac{\text{s}^2}{\text{m}} = \text{kg}\cdot\text{s}$، وهي ليست وحدة الضغط.', '["","بشطب الوحدات لا تنتج هذه الوحدة؛ فالناتج kg·s.","هذا ناتج ضرب الوحدات بدل قسمتها على m/s².","كون الوحدات من النظام الدولي لا يضمن أن ناتجها وحدة الضغط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-18T12:34:59.093Z"}'::jsonb),
('mcq', 3, 3, 'وحدة $vt$ هي $\frac{\text{m}}{\text{s}} \cdot \text{s} = \text{m}$، وهي وحدة الطرف الأيسر؛ فالمعادلة صحيحة من حيث الوحدات.', '["وحدة الطرف الأيمن $\\text{m/s}^2$ لا m.","وحدة الطرف الأيمن $\\text{s}^2/\\text{m}$ لا m.","وحدة الطرف الأيمن $\\text{m}\\cdot\\text{s}$ لا m.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-18T12:34:59.094Z"}'::jsonb),
('mcq', 4, 2, '$B = \frac{F}{qv}$، فوحدتها $\frac{\text{kg}\cdot\text{m/s}^2}{(\text{A}\cdot\text{s})(\text{m/s})} = \frac{\text{kg}\cdot\text{m/s}^2}{\text{A}\cdot\text{m}} = \text{kg/(A}\cdot\text{s}^2)$.', '["نتجت من قسمة وحدة القوة على وحدة الشحنة فقط دون القسمة على وحدة السرعة.","شُطبت ثانية زائدة؛ فحاصل ضرب وحدتي الشحنة والسرعة $(\\text{A}\\cdot\\text{s})(\\text{m/s}) = \\text{A}\\cdot\\text{m}$، فتبقى $\\text{s}^2$ من وحدة القوة في المقام.","","ضُربت وحدة القوة في وحدة السرعة بدل القسمة عليها: $\\frac{(\\text{kg}\\cdot\\text{m/s}^2)(\\text{m/s})}{\\text{A}\\cdot\\text{s}}$."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-11-18T12:34:59.094Z"}'::jsonb),
('mcq', 5, 1, 'وحدة التسارع m/s²؛ فظهور الإجابة بوحدة m/s يدل على وجود خطأ في الحل يجب البحث عنه.', '["وحدة m/s للسرعة لا للتسارع.","","إشارة القيمة لا تصحح خطأ الوحدة.","الضرب في عدد لا يغير الوحدة؛ والخطأ في خطوات الحل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-18T12:34:59.094Z"}'::jsonb),
('mcq', 6, 0, 'العملية الصحيحة قسمة المسافة على السرعة ثم الضرب في 1000، لأن $\frac{\text{km}}{\text{m/s}} = \frac{\text{km}\cdot\text{s}}{\text{m}}$، وبالضرب في $\frac{1000\ \text{m}}{1\ \text{km}}$ تُشطب km وm فيبقى s.', '["","ضرب km في m/s يعطي وحدة $\\text{km}\\cdot\\text{m/s}$ لا زمنًا.","الناتج يحتوي km/m، ويجب ضربه في 1000 m/1 km لا القسمة عليه.","الضرب لا يعطي وحدة زمن مهما كان العامل العددي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-18T12:34:59.094Z"}'::jsonb),
('mcq', 7, 3, 'في التعويض الصحيح يُضرب في $\frac{1000\ \text{g}}{1\ \text{kg}}$ فتصبح الوحدات $\frac{\text{N}}{\text{g}} \times \frac{\text{g}}{\text{kg}} = \frac{\text{N}}{\text{kg}} = \text{m/s}^2$، والناتج $a = \frac{2.7}{0.350} \approx 7.7\ \text{m/s}^2$.', '["معامل التحويل مقلوب؛ فلا تُشطب g وتبقى الوحدة $\\text{N}\\cdot\\text{kg/g}^2$.","الوحدة N/g ليست m/s²؛ يجب تحويل الكتلة إلى kg.","التسارع يساوي القوة مقسومة على الكتلة لا مضروبة فيها.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-18T12:34:59.095Z"}'::jsonb),
('essay', 1, null::int, null, null, 'وحدة الطرف الأيمن: $\frac{\text{m}}{\text{s}^2} \cdot \text{s}^2 = \text{m}$ (العدد $\frac{1}{2}$ ليس له وحدة). وهي وحدة المسافة؛ إذن العلاقة صحيحة من حيث الوحدات.', '["تعويض الوحدات في الطرف الأيمن","العدد 1/2 بلا وحدة","شطب s² والحصول على m","الحكم بصحة العلاقة"]'::jsonb, '["$\\frac{\\text{m}}{\\text{s}^2} \\times \\text{s}^2$","$= \\text{m}$","وحدة الطرفين واحدة"]'::jsonb, '[{"element":"تعويض الوحدات","marks":1},{"element":"الشطب والناتج","marks":1},{"element":"الحكم","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"تحقق صحيح كامل"},{"level":"1–2 درجة","description":"تعويض صحيح مع خطأ في الشطب أو دون حكم"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ترك وحدة الزمن غير مربعة","إعطاء العدد 1/2 وحدة","عدم المقارنة بوحدة الطرف الأيسر"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-18T12:34:59.095Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) الوحدات: $\frac{\text{kg}}{\text{A}\cdot\text{s}^2} \cdot \text{A}\cdot\text{s} \cdot \frac{\text{m}}{\text{s}} = \frac{\text{kg}\cdot\text{m}}{\text{s}^2} = \text{N}$، وهي وحدة القوة؛ فالمعادلة صحيحة. (ب) $F = (4.5)(1.6 \times 10^{-19})(2.4 \times 10^5) \approx 1.7 \times 10^{-13}\ \text{N}$.', '["التعويض بالقيم","شطب A وs والحصول على kg·m/s²","kg·m/s² = N","الناتج $\\approx 1.7 \\times 10^{-13}\\ \\text{N}$"]'::jsonb, '["$F = (4.5\\ \\text{T})(1.6 \\times 10^{-19}\\ \\text{A}\\cdot\\text{s})(2.4 \\times 10^5\\ \\text{m/s})$","الوحدات: $\\frac{\\text{kg}}{\\text{A}\\cdot\\text{s}^2} \\cdot \\text{A}\\cdot\\text{s} \\cdot \\frac{\\text{m}}{\\text{s}} = \\text{kg}\\cdot\\text{m/s}^2 = \\text{N}$","$F = 1.728 \\times 10^{-13} \\approx 1.7 \\times 10^{-13}\\ \\text{N}$"]'::jsonb, '[{"element":"التعويض","marks":1},{"element":"تحليل الوحدات","marks":2},{"element":"الحساب بأرقام معنوية صحيحة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة"},{"level":"2–3 درجات","description":"تحليل وحدات صحيح مع خطأ في الحساب أو الأرقام المعنوية"},{"level":"1 درجة","description":"التعويض بالقيم فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["خطأ في جمع أسس العدد 10","كتابة الناتج بأرقام معنوية أكثر من اللازم","عدم شطب الوحدات بوصفها كميات جبرية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-11-18T12:34:59.095Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) وحدة $\frac{v}{d}$ هي $\frac{\text{m/s}}{\text{m}} = \frac{1}{\text{s}}$، وليست وحدة الزمن s؛ إذن العلاقة خاطئة. (ب) العلاقة الصحيحة $t = \frac{d}{v}$، ووحدتها $\frac{\text{m}}{\text{m/s}} = \text{s}$، و$t = \frac{150}{30} = 5.0\ \text{s}$.', '["وحدة علاقة الطالب 1/s","الحكم بخطأ العلاقة","العلاقة الصحيحة t = d/v","وحدة الناتج s","t = 5.0 s"]'::jsonb, '["$\\frac{\\text{m/s}}{\\text{m}} = \\text{s}^{-1}$ ← ليست وحدة زمن","$t = \\frac{d}{v}$: $\\frac{\\text{m}}{\\text{m/s}} = \\text{s}$","$t = \\frac{150\\ \\text{m}}{30\\ \\text{m/s}} = 5.0\\ \\text{s}$"]'::jsonb, '[{"element":"تحليل وحدات علاقة الطالب","marks":1},{"element":"الحكم","marks":1},{"element":"العلاقة الصحيحة","marks":1},{"element":"التحقق من الوحدة","marks":1},{"element":"الحساب","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة صحيحة"},{"level":"3–4 درجات","description":"حكم صحيح مع خطأ في الحساب أو التحقق"},{"level":"1–2 درجة","description":"كتابة العلاقة الصحيحة دون تحليل الوحدات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الحكم على العلاقة بالقيمة العددية لا بالوحدة","إهمال كتابة الوحدة في الناتج","الخلط بين قسمة الوحدات وضربها"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-18T12:34:59.095Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'P1-C1-L2-O21') and x.type = v.type and x.number = v.number
