('mcq', 1, 'ما المقصود بتحليل الوحدات؟', null, null, '["مقارنة كمية مجهولة بكمية أخرى معيارية","تقارب نتائج القياس بعضها من بعض","التعامل مع الوحدات باعتبارها كميات جبرية","اتفاق نتائج القياس مع القيمة المقبولة"]'::jsonb, 'تذكر', 'تذكر تعريف', 'سهل', 'الكتاب ص 18 — تحليل الوحدات'),
('mcq', 2, 'ما معامل التحويل؟', null, null, '["معامل ضرب يساوي واحدًا صحيحًا (1)","معامل ضرب يساوي 1000 دائمًا","عدد يُضاف إلى القيمة لتحويل وحدتها","النسبة بين القيمة المقيسة والمقبولة"]'::jsonb, 'تذكر', 'تذكر تعريف', 'سهل', 'الكتاب ص 18 — تحليل الوحدات ومعامل التحويل'),
('mcq', 3, 'أيّ مما يأتي يمثل معامل تحويل صحيحًا؟', null, null, '["$\\frac{1000\\ \\text{kg}}{1\\ \\text{g}}$","$\\frac{100\\ \\text{m}}{1\\ \\text{km}}$","$\\frac{60\\ \\text{s}}{1\\ \\text{h}}$","$\\frac{1000\\ \\text{g}}{1\\ \\text{kg}}$"]'::jsonb, 'فهم', 'تمييز مثال', 'متوسط', 'الكتاب ص 18 — تحليل الوحدات ومعامل التحويل'),
('mcq', 4, 'لماذا لا يتغير مقدار الكمية الفيزيائية عند ضربها في معامل تحويل؟', null, null, '["لأن معامل التحويل لا يحتوي على وحدات","لأن معامل التحويل يساوي واحدًا صحيحًا","لأن معامل التحويل يُضاف إلى الكمية","لأن معامل التحويل يساوي 1000 دائمًا"]'::jsonb, 'فهم', 'تفسير مفهوم', 'متوسط', 'الكتاب ص 18 — تحليل الوحدات ومعامل التحويل'),
('mcq', 5, 'فيمَ يُستخدم تحليل الوحدات؟', null, null, '["تحديد القيمة المقبولة للكمية المقيسة في التجربة","تحديد دقة أداة القياس من تدريجها","تجنب خطأ اختلاف زاوية النظر","التحقق من صحة الإجابة وإيجاد معاملات التحويل"]'::jsonb, 'تذكر', 'تذكر استخدام', 'متوسط', 'الكتاب ص 18، 25 — تحليل الوحدات'),
('mcq', 6, 'لتحويل 1.34 kg إلى g، أيّ معاملي التحويل نختار، ولماذا؟', null, null, '["$\\frac{1000\\ \\text{g}}{1\\ \\text{kg}}$؛ لأنه يشطب kg ويُبقي g","$\\frac{1\\ \\text{kg}}{1000\\ \\text{g}}$؛ لأن kg يُكتب أولًا دائمًا","أيّهما؛ لأن كليهما يساوي واحدًا","$\\frac{100\\ \\text{g}}{1\\ \\text{kg}}$؛ لأنه يشطب kg ويُبقي g"]'::jsonb, 'فهم', 'اختيار معامل تحويل', 'صعب', 'الكتاب ص 18 — تحليل الوحدات ومعامل التحويل'),
('mcq', 7, 'في التحويل $\left(\frac{43\ \text{km}}{1\ \text{h}}\right)\left(\frac{1000\ \text{m}}{1\ \text{km}}\right)\left(\frac{1\ \text{h}}{60\ \text{min}}\right)\left(\frac{1\ \text{min}}{60\ \text{s}}\right) = 12\ \text{m/s}$، كم معامل تحويل استُخدم؟', null, null, '["أربعة معاملات","معاملان","ثلاثة معاملات","معامل واحد"]'::jsonb, 'فهم', 'تحليل سلسلة تحويل', 'صعب', 'الكتاب ص 18 — تحليل الوحدات ومعامل التحويل'),
('essay', 1, 'عرّف كلًّا من: (أ) تحليل الوحدات. (ب) معامل التحويل. ثم اكتب مثالًا لمعامل تحويل مستعينًا بالعلاقة 1 kg = 1000 g.', null, null, null, 'تذكر', 'تعريف مع مثال', 'سهل', 'الكتاب ص 18، 25 — تحليل الوحدات ومعامل التحويل'),
('essay', 2, 'من العلاقة 1 km = 1000 m: (أ) اكتب معاملي التحويل الممكنين. (ب) أيّهما تستخدم لتحويل 5.2 km إلى m؟ علّل باستخدام فكرة شطب الوحدات. (ج) نفّذ التحويل.', null, null, null, 'فهم', 'كتابة واختيار معامل تحويل', 'متوسط', 'الكتاب ص 18 — تحليل الوحدات ومعامل التحويل'),
('essay', 3, 'حوّل السرعة 5.30 m/s إلى km/h مستخدمًا معاملات التحويل، وبيّن كيف يؤكد تحليل الوحدات صحة خطواتك.', null, null, null, 'تطبيق', 'تحويل مع تحليل الوحدات', 'صعب', 'الكتاب ص 18 — مسائل تدريبية (12)')
