('mcq', 4, 1, 'معامل التحويل يساوي واحدًا صحيحًا، والضرب في واحد لا يغير مقدار الكمية، وإنما يغير الوحدة التي يُعبّر بها عنها.', '["معامل التحويل يحتوي على وحدات في بسطه ومقامه، وبها تُشطب الوحدات.","","معامل التحويل يُضرب في الكمية ولا يُضاف إليها.","معامل التحويل يساوي واحدًا، والأعداد الظاهرة فيه تختلف من تحويل إلى آخر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-18T12:34:59.096Z"}'::jsonb),
('mcq', 5, 3, 'يُستخدم تحليل الوحدات للتحقق من أن وحدات الإجابة صحيحة، ويُستخدم أيضًا في إيجاد معامل التحويل.', '["القيمة المقبولة يحددها خبراء مؤهلون بالقياس.","الدقة تحددها قيمة أصغر تدريج في الأداة.","يُتجنب هذا الخطأ بالنظر العمودي بعين واحدة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-18T12:34:59.096Z"}'::jsonb),
