('mcq', 7, 2, 'الكسور التي تساوي واحدًا هي: (1000 m/1 km) و(1 h/60 min) و(1 min/60 s)؛ فهي ثلاثة معاملات تحويل، أما 43 km/h فهي الكمية نفسها.', '["الكسر الأول هو الكمية المراد تحويلها (43 km/h) وليس معامل تحويل.","جميع الكسور الثلاثة الأخيرة تساوي واحدًا، فكلها معاملات تحويل.","","تحويل الساعة إلى ثوانٍ تم هنا على مرحلتين، إضافة إلى تحويل km إلى m."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-18T12:34:59.097Z"}'::jsonb),
('essay', 1, null::int, null, null, '(أ) تحليل الوحدات: طريقة التعامل مع الوحدات باعتبارها كميات جبرية. (ب) معامل التحويل: معامل ضرب يساوي واحدًا صحيحًا (1). مثال: $\frac{1\ \text{kg}}{1000\ \text{g}} = 1$ أو $\frac{1000\ \text{g}}{1\ \text{kg}} = 1$.', '["تعريف تحليل الوحدات","تعريف معامل التحويل","مثال صحيح"]'::jsonb, '[]'::jsonb, '[{"element":"تعريف تحليل الوحدات","marks":1},{"element":"تعريف معامل التحويل","marks":1},{"element":"المثال","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"تعريفان صحيحان مع مثال"},{"level":"1–2 درجة","description":"تعريف واحد صحيح أو مثال فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تعريف تحليل الوحدات بأنه تحويل الوحدات فقط","كتابة معامل تحويل لا يساوي واحدًا","الخلط بين معامل التحويل والبادئة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-18T12:34:59.097Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) $\frac{1000\ \text{m}}{1\ \text{km}}$ و$\frac{1\ \text{km}}{1000\ \text{m}}$، وكلاهما يساوي واحدًا. (ب) نستخدم $\frac{1000\ \text{m}}{1\ \text{km}}$ لأن km في المقام تُشطب مع km في الكمية فتبقى m. (ج) $5.2\ \text{km} \times \frac{1000\ \text{m}}{1\ \text{km}} = 5200\ \text{m}$.', '["معاملا التحويل","اختيار المعامل الصحيح","التعليل بشطب الوحدات","الناتج 5200 m"]'::jsonb, '["$5.2\\ \\text{km} \\times \\frac{1000\\ \\text{m}}{1\\ \\text{km}}$","$= 5200\\ \\text{m}$"]'::jsonb, '[{"element":"المعاملان","marks":1},{"element":"الاختيار والتعليل","marks":1},{"element":"الحساب","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"إجابة كاملة صحيحة"},{"level":"1–2 درجة","description":"خطأ في الاختيار أو الحساب"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["استخدام المعامل المقلوب فيكون الناتج 0.0052","نسيان كتابة الوحدة","عدم بيان أن المعاملين يساويان واحدًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-18T12:34:59.097Z"}'::jsonb),
('essay', 3, null::int, null, null, '$\left(\frac{5.30\ \text{m}}{1\ \text{s}}\right)\left(\frac{1\ \text{km}}{1000\ \text{m}}\right)\left(\frac{3600\ \text{s}}{1\ \text{h}}\right) = 19.1\ \text{km/h}$. تحليل الوحدات: m تُشطب مع m، وs مع s، فيبقى km/h وهي الوحدة المطلوبة، وكل معامل يساوي واحدًا فلا يتغير مقدار السرعة.', '["معامل m إلى km","معامل s إلى h","شطب الوحدات وبقاء km/h","الناتج 19.1 km/h بثلاثة أرقام معنوية"]'::jsonb, '["$5.30 \\times \\frac{1}{1000} \\times 3600$","$= 19.08 \\approx 19.1\\ \\text{km/h}$","الوحدات: $\\frac{\\text{m}}{\\text{s}} \\cdot \\frac{\\text{km}}{\\text{m}} \\cdot \\frac{\\text{s}}{\\text{h}} = \\frac{\\text{km}}{\\text{h}}$"]'::jsonb, '[{"element":"المعاملات","marks":2},{"element":"تحليل الوحدات","marks":1},{"element":"الناتج","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة"},{"level":"2–3 درجات","description":"معامل مقلوب أو خطأ في الأرقام المعنوية"},{"level":"1 درجة","description":"كتابة معامل واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["استخدام $\\frac{1\\ \\text{h}}{3600\\ \\text{s}}$ فيصبح الناتج صغيرًا جدًّا","كتابة الناتج 19.08 دون تقريب","نسيان شطب الوحدات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-18T12:34:59.097Z"}'::jsonb)
